/* techniques q05 (174 mục) — engine-API đợt 491-500 Ch.500 - gop trung 2026-07-21 - gop trung 2026-07-22 - gop trung 2026-07-22 - gop trung 2026-07-24 */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]=window.__LIBQ["the-gioi-hoan-my"]["q05"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]["techniques"]={"updatedAt":"2026-07-21","count":163,"techniques":[{"id":"tieu-truyen-tong-tran","name":"Tiểu truyền tống trận","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Hỏa quốc","soHuu":[],"blurb":"Trận pháp đặt tại cổng biệt viện tụ hội ở Hoàng Đô Hỏa quốc, dùng để sàng lọc tu vi và đưa người đạt yêu cầu vào bên trong.","detail":"Chỉ người có tu vi đạt tới cảnh giới nhất định mới có thể bước lên trận pháp. Khi vận chuyển, trận pháp truyền tống người đủ điều kiện từ cổng vào khu sân vườn của biệt viện.","nguon":["@c0402"]},{"id":"phap-hoa-kiep-van-hac-van-toc","name":"Pháp hóa kiếp vân của Hắc Vân tộc","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Hắc Vân tộc","soHuu":["Thiên tài số một Hắc Vân tộc"],"blurb":"Thần thông cho phép người thi triển hóa thân thành kiếp vân và dẫn động sấm chớp công kích đối thủ.","detail":"Thiên tài số một Hắc Vân tộc hóa toàn thân thành mây đen, diễn hóa cảnh tượng như thiên kiếp và dùng sấm chớp bao phủ võ đài khi giao chiến với Cửu đầu sư tử.","nguon":["@c0403"]},{"id":"sat-tran-chin-ky-hieu","name":"Sát trận chín ký hiệu","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Cửu đầu sư tử","soHuu":["Cửu đầu sư tử"],"blurb":"Sát trận được tạo thành khi chín đầu của Cửu đầu sư tử đồng thời phun ra và liên kết chín ký hiệu màu vàng.","detail":"Chín ký hiệu lấp lánh nối liền thành quang mang vàng và hóa thành sát trận, phá hủy sấm chớp cùng kiếp vân rồi giết thiên tài số một Hắc Vân tộc.","nguon":["@c0403"]},{"id":"dai-tran-nang-vo-dai","name":"Đại trận nâng võ đài","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Trận pháp nâng một bình đài quyết đấu khổng lồ lên không trung.","detail":"Ông lão trong trang viên kích hoạt đại trận để đưa bình đài lên trời, tạo nơi quyết đấu riêng và tránh làm hư hại dược thảo quý trong khu vực tụ hội.","nguon":["@c0403"]},{"id":"trang-vuc-than-the","name":"Tràng vực thân thể","cn":"","loai":"luyen-the","loaiLabel":"Năng lực luyện thể","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Khu vực áp chế hình thành khi bảo thể đạt tới mức cực kỳ mạnh mẽ, khiến đối thủ trực tiếp đối kháng bằng thân thể rơi vào thế bất lợi.","detail":"Tràng vực thân thể của Thạch Hạo có thể dùng khí thế áp chế và gây thương tích cho cả Vương giả Liệt Trận trước khi đôi bên thực sự giao thủ.","nguon":["@c0406"]},{"id":"sat-tran-tu-tuong","name":"Sát trận Tứ Tượng","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Viêm Mãng tộc","soHuu":["Lão già Viêm Mãng tộc"],"blurb":"Sát trận được dựng bằng bốn trận kỳ, có khả năng vây nhốt một tiểu thiên địa và luyện hóa mục tiêu bên trong.","detail":"Khi vận chuyển, trận pháp bùng phát sấm chớp, ánh lửa và ký hiệu dày đặc. Lão già Viêm Mãng tộc còn kết ấn, truyền từng luồng thần quang vào trận để tăng tốc tiêu diệt Thạch Hạo.","nguon":["@c0406"]},{"id":"kiem-y-tren-tam-da-thu","name":"Kiếm ý trên tấm da thú","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm ý","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Thạch Hạo"],"blurb":"Kiếm ý Thạch Hạo lĩnh ngộ từ một tấm da thú tại Hư Thần giới, có thể phát ra ngay cả khi thân thể bị giam cầm.","detail":"Thạch Hạo vận dụng kiếm ý để phun kiếm khí xuyên thủng lồng ngực một Vương giả Liệt Trận cảnh. Nó còn có thể phát kiếm khí từ gân mạch và khiếu huyệt để chống trả đối thủ và công kích Vòng Ngũ Hành khi không thể cử động thân thể.","nguon":["@c0408"]},{"id":"kiem-y-mot-cay-co","name":"Kiếm ý “một cây cỏ”","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm ý","phamCap":"Vô thượng","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Kiếm ý của một cây cỏ do thiên kiêu thượng cổ lưu lại, có thể hóa thành kiếm khí thông thiên với sức chém cực mạnh.","detail":"Thạch Hạo dùng kiếm ý này phá hủy hồ lô đen, chém đôi cường giả Hắc Vân tộc, giết Vương giả Hỏa Ngưu tộc, phá cốt thuẫn và chém mất tay chân của Tần Thủ Thành. Khi thi triển, hắn còn có thể hóa cả người thành kiếm thần để xuyên phá phù văn phòng hộ.","nguon":["@c0409","@c0490"]},{"id":"co-than-luyen-the","name":"Cổ thần luyện thể","cn":"","loai":"luyen-the","loaiLabel":"Phương thức luyện thể","phamCap":"","hePhai":"Cổ thần","soHuu":["Cửu đầu sư tử"],"blurb":"Phương thức luyện thể giúp Cửu đầu sư tử nhanh chóng tiến hóa và chuẩn bị trở thành sinh linh thuần huyết.","detail":"Cửu đầu sư tử sử dụng phương thức luyện thể này trong quá trình rèn luyện, kết hợp với Hoàng Kim Thần Lô và Cửu Luyện chân huyết để thúc đẩy tiến hóa, đoạt lấy thiên địa tạo hóa và nhanh chóng nâng cao tu vi.","nguon":["@c0410"]},{"id":"tran-phap-kinh-the-to-dia-thach-toc","name":"Trận pháp kinh thế của tổ địa Thạch tộc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Kinh thế","hePhai":"Thạch tộc","soHuu":["Tế Linh mạnh nhất của Thạch quốc"],"blurb":"Trận pháp che giấu tổ địa Thạch tộc, khiến cả đại năng cũng khó tìm ra nơi này.","detail":"Tế Linh mạnh nhất của Thạch quốc dùng di cốt bố trí trận pháp, bao phủ phạm vi hàng nghìn dặm quanh tổ địa Thạch tộc. Về sau, trận pháp bị Liễu Thần phá.","nguon":["@c0411"]},{"id":"bon-phuong-thuoc-truyen-thua-thach-quoc","name":"Bốn phương thuốc truyền thừa của Thạch quốc","cn":"","loai":"khac","loaiLabel":"Phương thuốc","phamCap":"Không rõ","hePhai":"Thạch quốc","soHuu":[],"blurb":"Bốn phương thuốc thuộc truyền thừa của Thạch quốc, có thể được trao cho Thạch Hạo nếu Nhân Hoàng chọn nó làm người kế vị.","detail":"Đây là bốn phương thuốc được truyền thừa tại Thạch quốc. Một Vương giả nhận định chúng có thể thuộc về Thạch Hạo nếu thiếu niên được Nhân Hoàng tuyển chọn làm người thừa kế, nhưng Thạch Hạo cho rằng Thạch thôn đã có phương thuốc hoàn hảo hơn.","nguon":["@c0412"]},{"id":"phuong-thuoc-tro-giup-thanh-ton-gia","name":"Phương thuốc trợ giúp thành Tôn giả","cn":"","loai":"khac","loaiLabel":"Phương thuốc","phamCap":"Không rõ","hePhai":"","soHuu":[],"blurb":"Phương thuốc có tác dụng trợ giúp người tu hành tiến tới cảnh giới Tôn giả, cần kỳ dược tại Hỏa Diễm sơn làm chủ dược.","detail":"Việc chuẩn bị phương thuốc đòi hỏi chủ dược sinh trưởng tại Hỏa Diễm sơn ở cực Tây Hoang Vực, cùng nhiều bảo dược và huyết nhục dị chủng quý hiếm. Khu vực có kỳ dược là tuyệt địa nguy hiểm, người tiến vào phải đối mặt với cảnh cửu tử nhất sinh.","nguon":["@c0412"]},{"id":"than-phap-cuc-toc-kim-si-dai-bang","name":"Thân pháp cực tốc của Kim Sí Đại Bằng","cn":"","loai":"than-thong","loaiLabel":"Thân pháp","phamCap":"Chưa rõ","hePhai":"Bộ tộc Kim Sí Đại Bằng","soHuu":["Huynh trưởng của thiếu niên tóc vàng"],"blurb":"Thân pháp của Kim Sí Đại Bằng cho phép người thi triển di chuyển với tốc độ cực nhanh, khiến phần lớn người chứng kiến không nhìn rõ quá trình tiếp cận.","detail":"Huynh trưởng của thiếu niên tóc vàng dùng thân pháp này tiến vào khu vườn nhanh đến mức nhiều người không nhận ra gã đã tới bằng cách nào. Thạch Hạo vẫn nhìn ra đây là thân pháp cực tốc của Kim Sí Đại Bằng.","nguon":["@c0413"]},{"id":"dai-dao-than-am-chua-dat-ten","name":"Đại đạo Thần âm chưa đặt tên","cn":"","loai":"than-thong","loaiLabel":"Thần thông âm thanh","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Thạch Hạo"],"blurb":"Thần thông âm thanh dung nhập hàm nghĩa đại đạo vào một tiếng hừ để chấn nhiếp đối thủ.","detail":"Thạch Hạo phát ra một tiếng hừ ẩn chứa hàm nghĩa đại đạo, khiến hư không rung động và tạo ra lực chấn kích như búa lớn, làm Kim Vân Thanh sắc mặt trắng bệch.","nguon":["@c0414"]},{"id":"loi-phap-cua-mo-viem","name":"Lôi pháp của Mộ Viêm","cn":"","loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"","hePhai":"Bổ Thiên các","soHuu":["Mộ Viêm","Thạch Hạo"],"blurb":"Lôi pháp do Mộ Viêm truyền cho Thạch Hạo, từng được tu luyện giữa tầng mây trong ngày mưa.","detail":"Mộ Viêm từng dẫn Thạch Hạo vào tầng mây có lôi kiếp để truyền dạy và giúp hắn luyện hóa lôi kiếp dịch trong hoàn cảnh cực kỳ nguy hiểm.","nguon":["@c0415"]},{"id":"co-tran-than-coc","name":"Cổ trận Thần cốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Cổ trận","hePhai":"","soHuu":[],"blurb":"Hệ thống khoảng một trăm trận pháp rườm rà nối liền thành một thể, phong tỏa và bảo vệ trung tâm Thần cốc.","detail":"Cổ trận có cấm chế vặn vẹo hư không, khiến việc quan sát từ trên cao không phản ánh cảnh tượng chân thực và có thể dùng vết nứt hư không xoắn nát kẻ xâm nhập. Ngay cả Tôn giả cũng khó cưỡng ép phá trận; Vân Hi nhận thấy khí tức của nó tương tự cổ trận tại Thái Cổ Thần Sơn và suy đoán có thể do Thiên Thần hoặc Thập Hung lưu lại, nhưng nguồn gốc chưa được xác nhận.","nguon":["@c0417"]},{"id":"hon-tram-tran-phap-bao-ve-linh-can","name":"Hơn trăm trận pháp bảo vệ linh căn","cn":"","loai":"khac","loaiLabel":"Trận pháp phong hộ","phamCap":"Có khả năng đạt cấp Thiên Thần","hePhai":"","soHuu":[],"blurb":"Hệ thống hơn trăm tòa trận pháp bao quanh cây nhỏ ba hoa trong Thần cốc, ngăn người ngoài tiếp cận linh căn.","detail":"Các trận pháp tạo thành lớp phong hộ ngăn cách đoàn Thạch Hạo với cây nhỏ như một vực sâu hư không. Cửu đầu sư tử nhận định hệ thống này có khả năng đạt cấp Thiên Thần.","nguon":["@c0418"]},{"id":"bi-phap-luyen-than-trong-dinh","name":"Bí pháp luyện thân trong đỉnh","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Bí pháp phối hợp pháp ấn, đạo hỏa trong cơ thể và linh diễm bên ngoài để luyện thân trong dược đỉnh.","detail":"Người tu luyện ngồi trong dược đỉnh, liên tục kết ấn và dùng nội ngoại hỏa phối hợp quá trình luyện dược. Phương pháp này đồng thời rèn luyện thân thể và cưỡng ép khai mở tiềm năng.","nguon":["@c0419"]},{"id":"tran-phap-che-phu-dinh-vien","name":"Trận pháp che phủ đình viện","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Hỏa Linh Nhi"],"blurb":"Trận pháp dùng trận kỳ bao phủ đình viện nhằm che giấu động tĩnh và dị tượng luyện thân.","detail":"Trận pháp được bố trí khi tinh khí tám phương, cuồng phong, lôi điện và linh diễm cùng hội tụ về dược đỉnh, giúp hạn chế việc dị tượng gây chú ý trong Dược đô.","nguon":["@c0419"]},{"id":"khac-tran-trong-co-the-liet-tran","name":"Khắc trận trong cơ thể Liệt Trận","cn":"","loai":"khac","loaiLabel":"Phương thức tu luyện","phamCap":"Liệt Trận trung kỳ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Phương thức khắc họa trận pháp ngay trong thân thể khi tu luyện cảnh giới Liệt Trận.","detail":"Sau khi tiến vào Liệt Trận trung kỳ, Thạch Hạo bắt đầu khắc trận pháp trong cơ thể để tiếp tục tăng cường sức mạnh và phát huy đặc trưng của cảnh giới Liệt Trận.","nguon":["@c0419"]},{"id":"phuong-phap-luyen-kim-dan-thuy-hoa-am-duong","name":"Phương pháp luyện Kim đan thủy hỏa âm dương","cn":"","loai":"khac","loaiLabel":"Luyện đan pháp","phamCap":"Chưa rõ","hePhai":"Luyện đan","soHuu":["Thạch Hạo"],"blurb":"Phương pháp luyện đan dung hợp thủy hỏa và hai khí âm dương, đồng thời thu nạp tinh hoa thiên địa để cô đọng Kim đan.","detail":"Dẫn hỏa tinh dưới lòng đất, linh dịch trên trời, sấm chớp và tinh hoa thiên địa hội tụ trong dược đỉnh. Kim đan luyện thành mang đạo vận, có thể tu bổ thân thể, mở bảo tàng thân thể và hỗ trợ củng cố cảnh giới.","nguon":["@c0420"]},{"id":"ban-tay-mau-vang-dat","name":"Bàn tay màu vàng đất","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Thần Dược môn","soHuu":["Thái thượng trưởng lão Thần Dược môn"],"blurb":"Thần thông hóa pháp lực thành một bàn tay lớn màu vàng đất, mang theo dao động khủng bố đánh về phía đối thủ.","detail":"Thái thượng trưởng lão Thần Dược môn thi triển đòn này với sức mạnh của vương giả đỉnh cao để công kích Thạch Hạo, nhưng bàn tay pháp lực bị một quyền của cậu đánh tan dễ dàng.","nguon":["@c0420"]},{"id":"chu-ngu","name":"Chữ Ngự","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"","soHuu":["Cô gái bí ẩn áo xám"],"blurb":"Thần thông phòng ngự được cô gái áo xám viết thành một chữ vàng trên ngực Lâm Côn.","detail":"Chữ Ngự phát sáng khi Lâm Côn bị tấn công, liên tiếp tiêu diệt sấm chớp và hóa giải bảo thuật Toan Nghê do Thạch Hạo thi triển bằng thực lực Liệt Trận cảnh.","nguon":["@c0421"]},{"id":"tran-phap-gieng-to","name":"Trận pháp Giếng tổ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Trận pháp Thần Linh","hePhai":"Thần Dược môn","soHuu":[],"blurb":"Hệ thống vô số trận pháp do Thần Linh bố trí để bảo vệ Giếng tổ của Thần Dược môn.","detail":"Trận pháp bao quanh một cửa Sinh có sinh cơ và tiên khí dồi dào. Người bình thường xâm nhập chắc chắn phải chết, trong khi cô gái áo xám có thể tự do đi vào khu vực này.","nguon":["@c0421"]},{"id":"tha-tam-thong","name":"Tha tâm thông","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":[],"blurb":"Thần thông được Thạch Hạo suy đoán Long Nữ nắm giữ sau khi nàng phản ứng với những ý nghĩ hắn chưa nói thành lời. (+) Thần thông có khả năng đọc tâm tư của người khác. [CAN-SOAT-GOP]","detail":"Thạch Hạo nghi ngờ cô gái áo xám nắm giữ Tha tâm thông sau khi nàng nhìn thấu những suy nghĩ riêng tư của nó, nhưng năng lực này chưa được xác nhận trực tiếp.","nguon":["@c0422","@c0851"],"tabs":{}},{"id":"trung-dong-hop-nhat-va-phan-tach","name":"Trùng Đồng hợp nhất và phân tách","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Cô gái bí ẩn áo xám"],"blurb":"Năng lực dung hợp hai con ngươi của Trùng Đồng thành một và phân tách trở lại khi cần.","detail":"Khi cô gái áo xám phân tách Trùng Đồng, dị tượng như đại tinh hủy diệt và khí hỗn độn xuất hiện, đồng thời tâm tình của người đối diện cũng bị ảnh hưởng. Khi Trùng Đồng hợp nhất trở lại, tác động lên Thạch Hạo biến mất.","nguon":["@c0422"]},{"id":"than-thong-toan-nghe-mau-tim","name":"Thần thông Toan Nghê màu tím","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Lôi điện thần thông ngưng tụ thành Toan Nghê màu tím, mang theo dày đặc tia điện để công kích đối thủ.","detail":"Thạch Hạo thi triển thần thông này khi giao chiến với Lâm Côn. Toan Nghê màu tím lao tới, dùng lôi điện nhấn chìm đối phương và khiến ông ta kinh hãi, phải chịu thua.","nguon":["@c0423"]},{"id":"he-thong-than-tran-than-coc","name":"Hệ thống thần trận Thần cốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần trận","hePhai":"Thần cốc","soHuu":[],"blurb":"Hệ thống hơn trăm tầng thần trận bao phủ Thần cốc, mỗi tầng chứa một không gian rộng lớn và tàn dư phù văn nguy hiểm.","detail":"Ba tầng đầu từng bị cổ nhân phá mở một phần. Một cường giả có khả năng đã đạt cấp Thần và mang theo trận đồ cũng chỉ vượt qua hơn hai tầng trước khi bị trận văn nghiền ép, cho thấy các tầng sâu có uy lực cực kỳ đáng sợ.","nguon":["@c0424"]},{"id":"tran-phap-tu-linh-than-coc","name":"Trận pháp tụ linh Thần cốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thần cốc","soHuu":[],"blurb":"Trận pháp hội tụ tinh khí và linh mạch từ khu vực rộng lớn quanh Thần cốc về khe lõm tại trung tâm.","detail":"Đây là một bộ phận trong hệ thống trận pháp của Thần cốc, có khả năng rút tinh hoa của sinh linh tử nạn trong trận và dồn linh khí về khu vực chứa linh căn thiên địa.","nguon":["@c0424"]},{"id":"tran-phap-thien-than","name":"Trận pháp Thiên Thần","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thiên Thần","hePhai":"","soHuu":[],"blurb":"Trận pháp nguy hiểm đủ sức tiêu diệt cường giả cấp Thần và chặn mọi hành vi thăm dò.","detail":"Trận pháp có thể chặt đứt hoặc nuốt mất thần niệm thăm dò, đồng thời tự phát sát quang tấn công kẻ xâm nhập. Chim loan năm màu bị phản chấn thổ huyết khi thử trận, nhưng sát quang của trận pháp không thể phá hủy Thế giới hộp báu.","nguon":["@c0425"]},{"id":"tran-phap-ap-duong-va-truyen-tong-hoang-diep","name":"Trận pháp ấp dưỡng và truyền tống Hoàng điệp","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Dược thần","soHuu":["Dược thần"],"blurb":"Trận pháp do Dược thần bố trí để ấp dưỡng trứng Hoàng điệp bằng tinh hoa địa mạch, sau đó truyền tống nó trở lại bình Thần Băng.","detail":"Trận pháp đặt tại địa mạch tổ căn dưới Dược đô, giúp trứng Hoàng điệp hấp thu tinh hoa thiên địa trong thời gian ấp dưỡng. Khi cơ chế vận hành, trứng được truyền tống trở lại bình Thần Băng và tiếp tục bị phong ấn.","nguon":["@c0426"]},{"id":"cam-che-thuong-co-duoi-duoc-do","name":"Cấm chế thượng cổ dưới Dược đô","cn":"","loai":"khac","loaiLabel":"Cấm chế","phamCap":"Thượng cổ","hePhai":"Dược thần","soHuu":["Dược thần"],"blurb":"Cấm chế liên kết tế đàn dưới lòng đất Dược đô với địa mạch tổ căn, dùng để đưa bình Thần Băng ra ngoài.","detail":"Dựa theo ghi chép trên tấm da thú của Dược thần, Thạch Hạo và những người đồng hành tìm thấy một tế đàn nhỏ dưới lòng đất Dược đô. Sau khi tế đàn được kích hoạt, cơ chế liên kết với địa mạch tổ căn vận hành và truyền tống bình Thần Băng khỏi đáy ao linh dịch.","nguon":["@c0426"]},{"id":"tran-phap-phong-an-duoi-nui-thap","name":"Trận pháp phong ấn dưới núi thấp","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Dược Thần","soHuu":["Dược Thần"],"blurb":"Trận pháp dưới núi thấp tại trung tâm Dược đô, có tác dụng phong tỏa linh khí và trấn áp vật mạnh dưới lòng đất.","detail":"Trận pháp do Dược Thần bố trí dưới núi thấp, khiến linh khí bị giữ trong lòng đất và trấn áp vật mạnh. Khi bình Thần Băng xuất thế, linh khí cùng dị tượng tràn lên, khiến người của Thần Dược môn nghi ngờ trận pháp đã tổn hại.","nguon":["@c0427"]},{"id":"thai-co-tran-phap-roi-dai-vuc-lao-tu","name":"Thái Cổ trận pháp rời đại vực lao tù","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thái Cổ","hePhai":"Thiên Nhân Tộc","soHuu":[],"blurb":"Một trận pháp cổ xưa dùng để rời khỏi đại vực lao tù, cần đôi bao cổ tay của Thiên Nhân Tộc làm chìa khóa mở ra.","detail":"Ghi chép về trận pháp được Thiên Nhân Tộc phát hiện khi chỉnh lý cốt thư do Thái Cổ Thiên Nhân để lại. Văn tự trên trận chỉ cho biết nó có thể đưa người rời khỏi đại vực lao tù, không nói rõ điểm đến; bí mật này được Thiên Thần Sơn che giấu vì có thể dẫn tới sự tranh đoạt của các đại giáo.","nguon":["@c0430"]},{"id":"tran-phap-thai-co-thien-nhan-toc","name":"Trận pháp thái cổ của Thiên Nhân tộc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thái cổ","hePhai":"Thiên Nhân tộc","soHuu":["Thiên Nhân tộc"],"blurb":"Trận pháp được Thiên Nhân tộc chuẩn bị để bí mật đưa sinh linh rời khỏi đại vực trước khi đại kiếp xảy ra.","detail":"Việc khởi động trận pháp đòi hỏi Thiên Nhân tộc tìm đủ chìa khóa. Các Tôn giả của tộc ẩn mình chờ thời cơ, tránh để kế hoạch rời khỏi đại vực bị nguồn sức mạnh đứng sau đại kiếp phát hiện.","nguon":["@c0431"]},{"id":"tran-phap-che-giau-than-son-thien-nhan-toc","name":"Trận pháp che giấu Thần sơn Thiên Nhân tộc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thiên Nhân tộc","soHuu":["Vân Hi"],"blurb":"Trận pháp che khuất tòa Thần sơn trọng yếu của Thiên Nhân tộc, khiến người ngoài bình thường không thể nhìn thấy.","detail":"Vân Hi mở trận pháp khi dẫn đoàn người vào tịnh thổ, làm tòa Thần sơn hùng vĩ vốn bị che giấu hiện ra trước mắt mọi người.","nguon":["@c0434"]},{"id":"phap-tuong-cua-lieu-than","name":"Pháp tướng của Liễu Thần","cn":"","loai":"than-thong","loaiLabel":"Pháp tướng","phamCap":"","hePhai":"","soHuu":["Liễu Thần"],"blurb":"Pháp tướng siêu phàm của Liễu Thần, được bao quanh bởi thần hỏa và vô số điểm sáng tựa ba ngàn thế giới.","detail":"Thạch Hạo từng tận mắt nhìn thấy nhưng không thể lưu giữ rõ dung mạo trong trí nhớ. Tiểu Tháp nhận định rằng nếu hình dáng Pháp tướng này được người Hạ giới biết đến thì có thể gây nên sóng gió lớn tại Thượng giới.","nguon":["@c0434"]},{"id":"tran-phap-duy-tri-duoc-dien-thien-than-son","name":"Trận pháp duy trì dược điền Thiên Thần sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thiên Thần sơn","soHuu":[],"blurb":"Trận pháp do một vị Thiên Thần bố trí trong dược điền, giúp tinh khí luôn dồi dào và tẩm bổ linh dược cùng sinh trưởng.","detail":"Trận pháp duy trì môi trường trong dược điền Thiên Thần sơn, kết hợp nguồn tinh khí dồi dào để nuôi dưỡng số lượng lớn linh dược.","nguon":["@c0435"]},{"id":"tran-phap-phan-chia-thien-than-son","name":"Trận pháp phân chia Thiên Thần sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thiên Thần sơn","soHuu":[],"blurb":"Hệ thống trận pháp chia Thiên Thần sơn thành nhiều khu vực biệt lập, khiến mỗi nơi tựa như một tiểu thế giới.","detail":"Trận pháp ngăn cách các khu vực trên thần sơn, đồng thời che giấu phần không gian chân chính bên trong và tạo nên nhiều khu vực riêng biệt.","nguon":["@c0435"]},{"id":"tran-phap-cap-thien-than-bao-ve-thanh-duoc","name":"Trận pháp cấp Thiên Thần","cn":"","aliases":["Trận pháp bảo vệ Thánh dược"],"loai":"khac","loaiLabel":"Trận pháp","phamCap":"Cấp Thiên Thần","hePhai":"Thiên Thần sơn","soHuu":[],"blurb":"Trận pháp cấp Thiên Thần bao quanh khu vực cất giữ Dẫn Hồn Liên, có thể gây nguy hiểm đến tính mạng nếu bị tùy tiện xâm phạm.","detail":"Trận pháp bảo vệ khu vực Thánh dược trong tiểu thế giới của Thiên Thần sơn. Trận pháp hiện không còn nguyên vẹn, còn Khổng Cầu Kỷ tuyên bố mình biết cách tu bổ.","nguon":["@c0435"]},{"id":"co-tran-vuot-gioi-thien-than-son","name":"Cổ trận vượt giới của Thiên Thần Sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thiên Thần Sơn","soHuu":["Thiên Thần Sơn"],"blurb":"Cổ trận nằm trong bãi đá phía sau Thiên Thần Sơn, là con đường được dùng để vượt giới rời khỏi Hoang Vực trước đại kiếp.","detail":"Trận pháp đã bị thời gian bào mòn và hư hại nghiêm trọng. Những phần ghi chép trong trận đồ của Nhị Ngốc Tử có thể bổ khuyết chỗ thiếu, nhưng quá trình khôi phục cần hơn chục loại thần liệu quý hiếm mà bảo khố Thiên Thần Sơn không thể cung cấp đầy đủ.","nguon":["@c0436"]},{"id":"bo-phap-bang-toc","name":"Bộ pháp Bằng tộc","cn":"","loai":"than-thong","loaiLabel":"Thân pháp","phamCap":"","hePhai":"Bằng tộc","soHuu":["Thạch Hạo"],"blurb":"Bộ pháp mang áo nghĩa chí cao của Bằng tộc, được Thạch Hạo cố ý thi triển trước mặt Kim Sí Đại Bằng tộc.","detail":"Khi thi triển, phù văn màu vàng lóe lên dưới chân người sử dụng. Thạch Hạo vận dụng bộ pháp này để lập tức bước đến bên cạnh Vân Hi, đồng thời khiêu khích những người thuộc Kim Sí Đại Bằng tộc.","nguon":["@c0438"]},{"id":"than-thong-dien-bien-phu-van-cua-tieu-thap","name":"Thần thông diễn biến phù văn của tiểu tháp","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tiểu tháp","soHuu":["Tiểu tháp"],"blurb":"Tiểu tháp diễn hóa phù văn, giúp Thạch Hạo quan sát một phần huyền bí ẩn bên trong trận pháp trên Thiên Thần sơn.","detail":"Thần thông này diễn biến phù văn để mở rộng khả năng quan sát của Thạch Hạo, khiến cậu nhìn thấy một phần huyền bí trong trận pháp cùng khí tức thần bí quanh dấu chân cổ xưa.","nguon":["@c0439"]},{"id":"truyen-tong-tran-thai-co","name":"Truyền tống trận Thái cổ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Truyền tống trận có từ thời Thái cổ, cần lượng lớn thần liệu để tu bổ.","detail":"Các cường tộc liên hợp thu gom thần liệu từ nhiều Thần sơn để tu bổ Truyền tống trận Thái cổ, vì vậy ban đầu không muốn chia số vật liệu quý hiếm này cho Thạch Hạo.","nguon":["@c0440"]},{"id":"tran-phap-trong-thon-cua-thach-hao","name":"Trận pháp trong thôn của Thạch Hạo","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Hệ thống trận pháp trong thôn đã hư hại nhiều và cần được sửa chữa toàn diện.","detail":"Thạch Hạo lấy tình trạng hư hại của các trận pháp trong thôn làm lý do yêu cầu thần liệu cùng vật liệu thông thường, cho biết chỉ dùng vật liệu quý hiếm vẫn không đủ để sửa chữa toàn bộ.","nguon":["@c0440"]},{"id":"thong-dao-hu-khong-cua-lieu-than","name":"Thông đạo hư không của Liễu Thần","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Đại thần thông","hePhai":"","soHuu":["Liễu Thần"],"blurb":"Liễu Thần trực tiếp mở thông đạo vượt không gian, đưa Thạch Hạo cùng đồng bạn rời khỏi Thần sơn mà không cần mượn trận pháp của bảy Thần sơn.","detail":"Thông đạo do Liễu Thần mở khiến cường giả các tộc biến sắc. Khi ngoại lực làm thông đạo dao động, đoàn người bên trong vẫn rời đi an toàn.","nguon":["@c0441"]},{"id":"dai-tran-bao-ho-thach-thon","name":"Đại trận bảo hộ Thạch thôn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Vô thượng","hePhai":"Thạch thôn","soHuu":["Liễu Thần"],"blurb":"Đại trận do Liễu Thần dùng hơn mười loại thần liệu bố trí trong chín ngày để bảo vệ Thạch thôn trước đại kiếp.","detail":"Trận pháp đoạt tạo hóa thiên địa, hợp nhất khả năng phòng ngự, tiến công và truyền tống. Khi hợp trận, tinh khí cùng ký hiệu đại đạo hiện lên trong hư không và bóng Thần khấu đầu, nhưng dị tượng bị Liễu Thần áp chế để không truyền ra ngoài.","nguon":["@c0442"]},{"id":"tran-phap-con-rua-gia","name":"Trận pháp con rùa giả","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":[],"blurb":"Trận pháp được Liễu Thần nghi ngờ là nguồn gốc của hình tượng con rùa khổng lồ mang Thần tàng Chí Tôn.","detail":"Trận pháp có thể bị điều khiển để mô phỏng một con rùa sống và cố ý tỏa ra sinh cơ, qua đó tạo giả tượng nhằm dẫn dụ mục tiêu. Khả năng con rùa thực chất là trận pháp vẫn chưa được xác nhận.","nguon":["@c0442"]},{"id":"bao-thuat-cua-lieu-than","name":"Bảo thuật của Liễu Thần","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Liễu Thần","soHuu":["Liễu Thần","Thạch Hạo"],"blurb":"Đại thần thông hộ thân được Liễu Thần truyền trực tiếp cho Thạch Hạo trước khi hắn rời Thạch thôn.","detail":"Pháp môn được truyền vào mi tâm Thạch Hạo bằng một cành liễu sáng rực. Vô số ký hiệu màu vàng tổ hợp thành phù văn nguyên thủy, trải qua ngàn vạn diễn biến rồi quy về một; việc lĩnh ngộ chú trọng đạo pháp tự nhiên và sự phù hợp của tâm cảnh.","nguon":["@c0443"]},{"id":"bao-thuat-cua-be-ngan","name":"Bảo thuật của Bệ Ngạn","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"","soHuu":["Bệ Ngạn"],"blurb":"Bảo thuật mạnh nhất được Bệ Ngạn thi triển để chống lại sự bắt giữ của xích thần trật tự.","detail":"Bệ Ngạn dùng bảo thuật này công kích hư không với sức mạnh cao nhất, nhưng vẫn không thể phá vỡ xích thần trật tự đang trói buộc và bắt nó đi.","nguon":["@c0444"]},{"id":"dan-dao-nhap-the","name":"Dẫn đạo nhập thể","cn":"","loai":"luyen-the","loaiLabel":"Pháp môn luyện thể và trúc cơ","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Pháp môn dẫn đạo ngấn và vô tận phù văn vào cơ thể nhằm gột rửa chân thân, rèn luyện thể xác và xây dựng căn cơ đại đạo.","detail":"Người thực hiện bắt giữ những mảnh vỡ đại đạo, dẫn ký hiệu vào thân thể rồi kết hợp chúng với bảo tàng thể xác. Phù văn có thể ngưng tụ thành đạo hỏa và đỉnh lô để nung luyện toàn thân; quá trình này rất nguy hiểm, có khả năng khiến người tu bị đại đạo nghiền nát. Khi thành công, thân thể trở nên gần gũi với đạo và dễ dung nạp, xây dựng phù văn hơn, tạo nền tảng cho những lần đột phá về sau nhưng không trực tiếp nâng cao cảnh giới hiện tại.","nguon":["@c0446"]},{"id":"tran-phap-than-linh","name":"Trận pháp Thần Linh","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần Linh","hePhai":"Thạch Quốc","soHuu":["Thạch Quốc"],"blurb":"Trận pháp phòng hộ từng bảo vệ Thạch đô bằng sức mạnh phù văn, nhưng đã bị đánh tan sau khi mở ra.","detail":"Trận pháp từng bảo vệ hoàng đô Thạch Quốc. Sau đại kiếp, trên tường thành chỉ còn dấu tích phù văn tàn dư, cho thấy trận pháp đã được kích hoạt nhưng vẫn không chống nổi lực lượng công phá.","nguon":["@c0447"]},{"id":"trang-vuc-muoi-dong-thien","name":"Tràng vực mười Động Thiên","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Thạch Hạo"],"blurb":"Thần thông trấn áp do Thạch Hạo triển khai bằng mười Động Thiên, có thể niêm phong một tiểu thiên địa.","detail":"Khi được triển khai tại Yên Vũ lâu, tràng vực phong kín không gian và khiến mọi vật bên trong rơi vào trạng thái bất động. Nguyệt Thiền tiên tử dùng Ngọc Kiếm rạch phá tràng vực để thoát ra.","nguon":["@c0448"]},{"id":"tran-phap-yen-vu-lau","name":"Trận pháp Yên Vũ lâu","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Yên Vũ lâu","soHuu":[],"blurb":"Hệ thống gồm nhiều trận pháp bảo vệ khu vực quanh Yên Vũ lâu.","detail":"Các trận pháp được kích phát trong cuộc giao chiến giữa Thạch Hạo và Nguyệt Thiền tiên tử, nhưng cuối cùng đều tan rã dưới sức mạnh của trận chiến.","nguon":["@c0448"]},{"id":"kiem-y-cong-co","name":"Kiếm ý cọng cỏ","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm quyết","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật kiếm đạo được Thạch Hạo lĩnh ngộ từ hình cọng cỏ trên da thú, là một trong những bảo thuật mạnh nhất của nó vào thời điểm này.","detail":"Khi vận dụng kiếm ý, Thạch Hạo có thể phát kiếm khí từ toàn thân để công phá trận pháp và pháp khí. Kiếm ý này từng khiến Đạo thư màu tím mất khống chế trong trận chiến với đạo sĩ bảo vệ sơn môn Bổ Thiên giáo.","nguon":["@c0449"]},{"id":"dai-tran-hoang-cung-thach-quoc","name":"Đại trận hoàng cung Thạch Quốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":[],"blurb":"Đại trận phòng thủ hoàng cung Thạch Quốc, có thể kích hoạt phù văn trên tường thành để công kích người xông cung.","detail":"Quân giữ hoàng cung khởi động đại trận nhằm ngăn cản Thạch Hạo tiến vào. Trận pháp từng bị phá trong hạo kiếp nên đã hư hại và không còn nguyên vẹn, nhưng khi vận chuyển vẫn tạo ra áp lực lớn.","nguon":["@c0449"]},{"id":"bat-hoai-kim-cuong-than","name":"Bất Hoại Kim Cương thân","cn":"","loai":"luyen-the","loaiLabel":"Công pháp luyện thể","phamCap":"","hePhai":"Tây Thiên giáo","soHuu":["Thanh niên tóc ngắn cầm bình bát"],"blurb":"Pháp môn luyện thể của Tây Thiên giáo, được thanh niên tóc ngắn tu luyện tới cực hạn.","detail":"Khi vận chuyển Bất Hoại Kim Cương thân, bên ngoài cơ thể người tu luyện lưu chuyển hào quang vàng nhạt.","nguon":["@c0451"]},{"id":"kiem-khi-do-dam","name":"Kiếm khí đỏ đậm","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Kiếm khí do Thạch Hạo phóng ra từ tay, có khả năng phá vỡ pháp khí phòng ngự và chém đứt thân thể đối thủ.","detail":"Thạch Hạo dùng luồng kiếm khí đỏ đậm chém đứt hai pháp khí được đưa ra cản trở, sau đó bổ đôi Chiến tướng bảo vệ hoàng cung ngay tại chỗ.","nguon":["@c0451"]},{"id":"tia-dien-vang-tim","name":"Tia điện vàng tím","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Tia điện đặc biệt màu vàng tím được Thạch Hạo bắn ra từ ngón tay.","detail":"Đòn đánh xuyên thủng phù văn hộ thể của một tu sĩ vực ngoại, giết đối phương tại chỗ và thiêu thân thể thành than đen.","nguon":["@c0451"]},{"id":"dao-lien-bo-bo-sinh","name":"Đạo liên bộ bộ sinh","cn":"","loai":"khac","loaiLabel":"Dị tượng gần Đạo","phamCap":"Chưa rõ","hePhai":"Đại đạo giao cảm","soHuu":["Thạch Hạo"],"blurb":"Dị tượng khiến sen vàng xuất hiện theo từng bước chân khi thân thể giao cảm sâu sắc với đại đạo.","detail":"Mỗi bước của Thạch Hạo sinh ra đạo liên màu vàng, kèm hương thơm và hào quang. Khi đạt tới cảnh giới cao hơn, dị tượng gần Đạo này có thể chuyển hóa thành sức chiến đấu thực sự.","nguon":["@c0452"]},{"id":"set-hinh-cau-noi-than-nhat","name":"Sét hình cầu nối thần nhật","cn":"","loai":"than-thong","loaiLabel":"Thần thông lôi điện","phamCap":"Chưa rõ","hePhai":"Lôi điện","soHuu":["Thạch Hạo"],"blurb":"Thần thông tạo thành chuỗi mười quả sét nối liền với thần nhật để công kích mục tiêu.","detail":"Thạch Hạo tạo ra mười quả sét hình cầu liên kết thành chuỗi và nối với thần nhật. Đòn đánh phá nát lệnh bài tổ truyền của Côn vương, đồng thời khiến Côn vương toàn thân cháy khét và trọng thương.","nguon":["@c0452"]},{"id":"ban-tay-the-gioi-kiem-khi","name":"Bàn tay thế giới kiếm khí","cn":"","loai":"than-thong","loaiLabel":"Thần thông dung hợp","phamCap":"Chưa rõ","hePhai":"Dung hợp nhiều bảo thuật","soHuu":["Thạch Hạo"],"blurb":"Chiêu thức dung hợp nhiều bảo thuật thành một bàn tay lớn như tiểu thế giới chứa vô tận kiếm khí.","detail":"Bàn tay lớn bao phủ mục tiêu bằng một tiểu thế giới kiếm khí. Thạch Hạo dùng chiêu này nghiền nát và chém tan long thể được tạo ra từ Dẫn Long thủ.","nguon":["@c0452"]},{"id":"chuong-than-ho-the","name":"Chuông thần hộ thể","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật hộ thể","phamCap":"Pháp môn bước đầu tự diễn biến","hePhai":"Bổ Thiên giáo","soHuu":["Kỳ tài Bổ Thiên giáo"],"blurb":"Pháp môn ngưng tụ phù văn hư không thành chuông thần để bảo vệ người thi triển.","detail":"Kỳ tài Bổ Thiên giáo kết hợp với thiên địa, ngưng tụ phù văn trong hư không thành chuông thần hộ thể. Chuông chặn được một đòn Côn Bằng nhưng sau đó nứt vỡ trước đợt công kích tiếp theo.","nguon":["@c0452"]},{"id":"dang-xa-hoa-than","name":"Đằng xà hóa thân","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn mô phỏng hung thú","phamCap":"Chưa rõ","hePhai":"Bổ Thiên giáo","soHuu":["Kỳ tài Bổ Thiên giáo"],"blurb":"Pháp môn khiến thân thể hóa thành ngân xà, phục vụ việc biến hóa và đào thoát.","detail":"Kỳ tài Bổ Thiên giáo làm thân thể hóa khói rồi dựng thành một con ngân xà để bỏ chạy. Pháp môn thể hiện con đường mô phỏng hung thú và chim chóc nhằm thúc đẩy bản thân tiến hóa.","nguon":["@c0452"]},{"id":"tran-phap-thuong-co-trung-uong-thien-cung","name":"Trận pháp Thượng cổ trong thiên cung","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thượng cổ","hePhai":"Thạch quốc","soHuu":[],"blurb":"Trận pháp phòng hộ được khắc trong Trung Ương Thiên Cung, có khả năng gia cố và bảo vệ đại điện.","detail":"Trận pháp giúp kết cấu Trung Ương Thiên Cung chịu được va chạm mạnh trong cuộc giao đấu giữa Thạch Hạo và Thạch Sùng mà không sụp đổ.","nguon":["@c0453"]},{"id":"tran-phap-than-linh-trung-uong-thien-cung","name":"Trận pháp thần linh Trung Ương Thiên Cung","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần linh","hePhai":"Thạch quốc","soHuu":["Thạch Sùng"],"blurb":"Trận pháp phòng hộ bố trí trên mười hai trụ đá của Trung Ương Thiên Cung, có tác dụng phong tỏa và ngăn cường giả xâm nhập.","detail":"Thạch Sùng kích hoạt trận pháp để ngăn Nguyệt Thiền tiên tử, Tần Lôn và Trượng Lục tiến vào hợp kích Thạch Hạo. Ba truyền nhân đại giáo không thể phá giải trận pháp ngay lập tức.","nguon":["@c0453"]},{"id":"long-khi-hoang-dao","name":"Long khí Hoàng đạo","cn":"","loai":"khac","loaiLabel":"Quyền năng Nhân Hoàng","phamCap":"","hePhai":"Hoàng đạo Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Khí vận Thạch Quốc gia trì cho Nhân Hoàng, hóa thành nhiều thiên long hữu hình để hộ thân và công kích.","detail":"Sau khi Thạch Hạo kế thừa ngôi vị, Long khí Hoàng đạo hội tụ quanh người, đánh vỡ pháp khí và trấn sát hàng chục cao thủ. Quyền năng này đủ sức áp chế cả tu sĩ Liệt Trận cảnh và có thể đồng thời bùng phát thành hàng chục luồng long khí lao lên trời.","nguon":["@c0456"]},{"id":"khong-tuoc-bao-thuat","name":"Khổng Tước bảo thuật","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Đại thần thông trấn giáo","hePhai":"Bất Lão sơn","soHuu":["Tần Lôn"],"blurb":"Bảo thuật diễn hóa khổng tước khổng lồ và thần quang năm màu, lấy biến hóa khéo léo hóa giải thế công mãnh liệt.","detail":"Đây là đại thần thông của Khổng Tước vương thời Thái cổ, được sinh linh thuần huyết lưu lại và trở thành truyền thừa trấn giáo của Bất Lão sơn. Tần Lôn dùng bảo thuật này đối đầu pháp môn Côn Bằng của Thạch Hạo.","nguon":["@c0456"]},{"id":"kiem-gioi-tu-mot-cay-co","name":"Kiếm giới từ một cây cỏ","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm đạo thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Kiếm đạo thần thông diễn hóa một cây cỏ thành kiếm quang mang theo giới lực, tiến tới hình thành một kiếm giới.","detail":"Thạch Hạo dùng một cây cỏ chém ra kiếm quang mang theo thế giới nhỏ và giới lực, thể hiện chân nghĩa một cọng cỏ hóa thành thiên đường. Kiếm giới này ép Trượng Lục phải vận dụng thần thông vô lượng và Bất Hoại Thân, cuối cùng vẫn đánh hắn bay ngược.","nguon":["@c0456"]},{"id":"than-thong-vo-luong","name":"Thần thông vô lượng","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Trượng Lục"],"blurb":"Thần thông tạo ra một biên giới rồi nhanh chóng mở rộng để đối kháng thế giới thần thông của đối thủ.","detail":"Trượng Lục thi triển Thần thông vô lượng khi bị kiếm giới của Thạch Hạo áp chế. Thủ đoạn này tạo ra rồi phóng lớn một biên giới, thuộc hệ thống thế giới thần thông mà Tây Phương giáo am hiểu.","nguon":["@c0456"]},{"id":"bat-hoai-than","name":"Bất Hoại Thân","cn":"","loai":"luyen-the","loaiLabel":"Luyện thể thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Trượng Lục"],"blurb":"Luyện thể thần thông khiến thân thể phát ánh vàng và tăng mạnh khả năng trực tiếp chống đỡ công kích.","detail":"Trượng Lục vận dụng Bất Hoại Thân để ngạnh kháng nhiều đợt tấn công của Thạch Hạo trong lúc đối đầu kiếm giới. Dù chống đỡ được liên tiếp vài lần, hắn cuối cùng vẫn bị đánh bay.","nguon":["@c0456"]},{"id":"sat-tran-cua-nguyet-thien","name":"Sát trận của Nguyệt Thiền","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Sát trận do Nguyệt Thiền kích hoạt, dùng trận văn và dấu ấn đỏ bao phủ mục tiêu để tiến hành vây giết.","detail":"Nguyệt Thiền tiên tử kích hoạt sát trận nhằm giết Thạch Hạo tại Hoàng cung Thạch Quốc. Khi Hoàng cung thông linh và thừa nhận tân Nhân Hoàng, trận văn trong các cung điện phản kích, tiêu diệt phù văn và phá hủy hoàn toàn sát trận.","nguon":["@c0456"]},{"id":"tran-van-hoang-cung-thach-quoc","name":"Trận văn Hoàng cung Thạch Quốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Hệ thống trận văn trong Hoàng cung Thạch Quốc có thể thông linh, bảo vệ tân Nhân Hoàng và phá hủy trận pháp ngoại lai.","detail":"Sau khi công nhận Thạch Hạo là tân hoàng, hàng loạt cung điện đồng thời phát sáng và liên kết thành một thể với hắn. Trận văn Hoàng cung sau đó tiêu diệt toàn bộ phù văn thuộc sát trận do Nguyệt Thiền bố trí.","nguon":["@c0456"]},{"id":"ngu-long-thuat","name":"Ngự Long thuật","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Một phần bảo thuật Chân Long","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Thần thông giúp Nguyệt Thiền tiên tử khống chế một con rồng để giao chiến.","detail":"Ngự Long thuật nằm trong hàng ngũ bảo thuật Chân Long. Nguyệt Thiền tiên tử dùng cánh tay khống chế rồng, đối đầu với kiếm khí cọng cỏ do Thạch Hạo diễn hóa.","nguon":["@c0457"]},{"id":"phu-van-ngu-hanh-cua-tan-lon","name":"Phù văn ngũ hành của Tần Lôn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Bất Lão sơn","soHuu":["Tần Lôn"],"blurb":"Bảo thuật ngũ hành giúp Tần Lôn phóng ra năm loại bảo quang và phù văn nguyên tố.","detail":"Tần Lôn khiến thân thể liên tục phát sáng, điều động phù văn ngũ hành và năm loại bảo quang quanh người để giao chiến với Chu Tước do Thạch Hạo phóng ra.","nguon":["@c0457"]},{"id":"chu-tuoc-bao-thuat-chua-neu-ten","name":"Chu Tước bảo thuật chưa nêu tên","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Chưa rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật giúp Thạch Hạo phóng ra một con Chu Tước đỏ rực như lửa để công kích.","detail":"Thạch Hạo há miệng phóng Chu Tước đỏ rực ra ngoài, dùng nó nghênh chiến phù văn ngũ hành và năm loại bảo quang của Tần Lôn.","nguon":["@c0457"]},{"id":"than-thong-chu-yem","name":"Thần thông Chu Yếm","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Đại thần thông, bảo thuật trấn tộc","hePhai":"Chu Yếm","soHuu":["Thạch Hạo"],"blurb":"Đại thần thông giúp người thi triển hóa thành ba đầu sáu tay, tăng mạnh khả năng vận dụng nhiều bảo thuật cùng lúc.","detail":"Thạch Hạo vận dụng thần thông Chu Yếm để lần lượt sinh thêm tay, sau đó hoàn chỉnh hình thái ba đầu sáu tay. Trạng thái này giúp hắn chồng chất nhiều bảo thuật và gia tăng thần lực khi phản công ba đại cao thủ.","nguon":["@c0458"]},{"id":"van-phap-bat-xam","name":"Vạn pháp bất xâm","cn":"","loai":"than-thong","loaiLabel":"Thần thông hộ thân","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Trạng thái hộ thân tạo ra một lớp khí mờ ảo có thể tiêu diệt phù văn công kích đang đánh tới.","detail":"Khi Thạch Hạo giao chiến với lực lượng ba giáo, lớp khí mờ ảo bao quanh cơ thể hắn triệt tiêu các phù văn công kích, khiến những đòn đánh bằng phù văn không thể xâm nhập.","nguon":["@c0458"]},{"id":"than-thong-ngu-hanh","name":"Thần thông Ngũ Hành","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Tần Lôn"],"blurb":"Thần thông Ngũ Hành có thể làm càn khôn điên đảo và khiến thiên địa trở nên hỗn loạn.","detail":"Tần Lôn triển khai thần thông Ngũ Hành trong cuộc liên thủ vây đánh Thạch Hạo. Khi được thúc đẩy toàn lực, thần thông làm thiên địa hỗn loạn, càn khôn điên đảo và gần như diễn hóa cảnh tượng hỗn độn.","nguon":["@c0458"]},{"id":"the-gioi-than-thong","name":"Thế Giới Thần Thông","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Trượng Lục"],"blurb":"Thần thông được Trượng Lục dùng toàn lực nhằm trấn áp đối thủ.","detail":"Sau khi toàn thân hóa vàng và biến thành hình thái mười tám cánh tay, Trượng Lục thi triển Thế Giới Thần Thông để trấn áp Thạch Hạo. Thế công này phối hợp với Bổ Thiên thuật và thần thông Ngũ Hành nhưng vẫn không thể áp chế đối phương.","nguon":["@c0458"]},{"id":"dai-tran-ho-thanh-hoang-do","name":"Đại trận hộ thành Hoàng Đô","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Đại trận hộ thành","hePhai":"Thạch Quốc","soHuu":["Thạch Quốc"],"blurb":"Đại trận bảo vệ và phong tỏa Hoàng Đô, có thể biến kinh thành thành vòng vây khép kín.","detail":"Thạch Hạo ra lệnh cho Chiến vương cùng các Vương hầu trung thành đóng cửa thành và mở đại trận hộ thành. Mục đích là phong tỏa Hoàng Đô, ngăn lực lượng ba giáo đang tan vỡ rút khỏi thành và nhốt họ lại để tiêu diệt.","nguon":["@c0458"]},{"id":"than-thong-ngan-ha-trong-mat","name":"Thần thông ngân hà trong mắt","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Thần thông phát động qua đôi mắt của Nguyệt Thiền tiên tử, tạo phù văn, sương trắng và vùng sáng tựa ngân hà để ngăn cản công kích.","detail":"Nguyệt Thiền tiên tử dùng thần thông này để chống lại mấy chục thiên long do long khí Hoàng đạo diễn hóa. Ánh sáng trắng phát ra từ đôi mắt có khả năng ngăn cản và luyện hóa các thiên long đang lao tới.","nguon":["@c0459"]},{"id":"bao-thuat-chan-long","name":"Bảo thuật Chân Long","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Bảo thuật tối cao chưa hoàn chỉnh","hePhai":"Chân Long","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Bảo thuật hiện hóa Chân Long được chàng trai thần bí dùng trong cuộc giao phong với truyền nhân Tiên Điện. (+) Bảo thuật mô phỏng Chân Long, được Nguyệt Thiền tiên tử dùng để cận chiến với pháp môn Côn Bằng. [CAN-SOAT-GOP]","detail":"Khi thi triển, Nguyệt Thiền tiên tử mô phỏng thân rồng bạch ngọc và kết long ấn để giao phong trực diện. Bảo thuật có uy lực đủ khiến đối thủ thông thường trọng thương hoặc nổ tung, nhưng phiên bản nàng sử dụng có khuyết điểm và bị Thạch Hạo nhận ra là chưa hoàn chỉnh.","nguon":["@c0459","@c0623"],"tabs":{}},{"id":"luc-than-tran","name":"Lục Thần trận","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Sát trận có thể giết Tôn giả","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Sát trận được Nguyệt Thiền tiên tử bố trí từ trước quanh linh hồ và vùng núi sông để vây giết Thạch Hạo.","detail":"Do tu vi và vật liệu có hạn, Nguyệt Thiền tiên tử chỉ bố trí một phần phù văn hệ lôi của Lục Thần trận. Khi được kích hoạt, trận pháp huy động lực lượng của khu vực rộng lớn, liên tục giáng tia điện và thần quang trong một canh giờ. Lôi lực phá hủy pháp khí thượng cổ của Thạch Hạo và có uy lực đủ đánh chết cường giả đỉnh cao, kể cả Tôn giả.","nguon":["@c0459"]},{"id":"bao-thuat-than-hoang","name":"Bảo thuật Thần Hoàng","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Bảo thuật Thập Hung không trọn vẹn","hePhai":"","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Bảo thuật diễn hóa Thần Hoàng, được Nguyệt Thiền tiên tử phối hợp với bảo thuật Chân Long để tạo thành thế long–hoàng. (+) Bảo thuật hoàn chỉnh ngang hàng với bảo thuật Chân Long, gồm nhiều thức biến hóa có uy lực tuyệt luân. [CAN-SOAT-GOP]","detail":"Khi thi triển, Nguyệt Thiền tiên tử diễn hóa một con phượng hoàng rực rỡ phía sau lưng. Bảo thuật này không trọn vẹn, nhưng khi kết hợp với bảo thuật Chân Long vẫn tạo ra sức công phạt mạnh mẽ.","nguon":["@c0460","@c0533"],"tabs":{}},{"id":"sat-tran-cua-da-than-thach","name":"Sát trận của Đả Thần Thạch","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Có thể đối phó đại năng thượng cổ","hePhai":"","soHuu":["Đả Thần Thạch","Thạch Hạo"],"blurb":"Một sát trận đáng sợ do Đả Thần Thạch truyền trận đồ cho Thạch Hạo, có khả năng đối phó đại năng thượng cổ.","detail":"Trận pháp cần nhiều vật liệu quý, trong đó có cả thần liệu, nhưng có thể chỉ dựng một phần để giảm tiêu hao. Thạch Hạo điều chỉnh trận nhằm bỏ qua người bình thường, chỉ phát động công kích với tu sĩ từ Tôn giả trở lên và xét ý đồ của người tiến vào.","nguon":["@c0461"]},{"id":"hoa-than-kim-bang","name":"Hóa thân Kim Bằng","cn":"","loai":"than-thong","loaiLabel":"Thần thông biến hóa","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thần thông biến hóa giúp Thạch Hạo hóa thành Kim Bằng để phi hành.","detail":"Sau khi bố trí trận pháp, xóa các dấu vết không cần thiết và để lại manh mối dẫn dụ tại vùng đất tai ương, Thạch Hạo hóa thành Kim Bằng bay trở về Hoàng đô.","nguon":["@c0461"]},{"id":"than-tran-thuong-co-hoang-cung","name":"Thần trận Thượng cổ hoàng cung","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thượng cổ","hePhai":"Thạch Quốc","soHuu":[],"blurb":"Thần trận bố trí trong hoàng cung Thạch Quốc, từng phối hợp với quốc vận bảo vệ Thạch Hoàng trong đại kiếp.","detail":"Trận pháp có thể tiêu diệt Tôn giả nhưng đã bị phá hủy hơn nửa sau đại kiếp, đặc biệt tổn hại nghiêm trọng tại trung ương Thiên cung. Thạch Hạo dự định dùng lượng lớn vật liệu để sửa chữa, hoàn thiện hệ thống phòng vệ và đối phó tu sĩ ba giáo.","nguon":["@c0462"]},{"id":"tran-phap-chong-thien-phat","name":"Trận pháp chống thiên phạt","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Thạch Quốc","soHuu":["Thạch Hoàng"],"blurb":"Trận pháp đáng sợ do Thạch Hoàng luyện hóa từ nhiều vật liệu trong bảo khố để chống lại thiên phạt.","detail":"Trong đại kiếp, Thạch Hoàng lấy nhiều vật liệu từ bảo khố và luyện hóa chúng thành trận pháp nhằm chống thiên phạt, khiến lượng vật liệu còn lại trong ngoại khố suy giảm đáng kể.","nguon":["@c0462"]},{"id":"than-thong-be-ngan","name":"Thần thông Bệ Ngạn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thiên giai","hePhai":"Thạch quốc","soHuu":[],"blurb":"Một trong những thần thông trấn quốc của Thạch quốc, hiện không còn hoàn chỉnh.","detail":"Truyền thừa này từng bị mất một số phù văn khi quốc vận Thạch quốc dao động.","nguon":["@c0463"]},{"id":"phap-mon-te-linh-truyen-xuong","name":"Pháp môn Tế Linh truyền xuống","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thiên giai","hePhai":"Thạch quốc","soHuu":[],"blurb":"Pháp môn trấn quốc thứ ba của Thạch quốc, do Tế Linh truyền xuống.","detail":"Truyền thừa này đã hoàn toàn thất truyền trong một lần náo loạn.","nguon":["@c0463"]},{"id":"bao-thuat-khong-tuoc","name":"Bảo thuật Khổng Tước","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"","soHuu":[],"blurb":"Bảo thuật từng được lưu giữ bằng một bức họa Khổng Tước trong Điển miếu.","detail":"Bức họa thể hiện thần quang năm màu có thể khiến trời cao rạn nứt, nhưng vật truyền thừa đã bị lấy khỏi Điển miếu trước khi Thạch Hạo tới.","nguon":["@c0463"]},{"id":"dai-tran-chu-tuoc-doanh","name":"Đại trận Chu Tước doanh","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Chu Tước doanh","soHuu":["Chỉ huy Chu Tước doanh","Các cao thủ Bất Lão sơn tại Chu Tước doanh"],"blurb":"Trận pháp phòng thủ được phe phản loạn tại Chu Tước doanh triển khai để chống quân triều đình.","detail":"Đây là lá bài mạnh nhất trong bố trí của phe phản loạn tại Chu Tước doanh. Trận pháp bị Thạch Hạo, Chiến Vương và thị vệ lớn tuổi liên thủ phá tan.","nguon":["@c0465"]},{"id":"dai-tran-ho-thanh-thach-do","name":"Đại trận hộ thành Thạch đô","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Thạch Quốc"],"blurb":"Trận pháp hộ thành phong tỏa Thạch đô, ngăn các chư hầu dùng tế đàn trong tộc mở đường trốn khỏi kinh thành.","detail":"Đại trận được mở từ trước và phối hợp với ảnh hưởng của tế đàn hoàng tộc Thạch Quốc để phong tỏa dịch chuyển khỏi Thạch đô. Vì sự phong tỏa này, Vũ tộc không thể dùng tế đàn trong phủ mở thông đạo hư không đào thoát.","nguon":["@c0466"]},{"id":"bi-phap-mua-sam-cua-vu-toc","name":"Bí pháp mưa sấm của Vũ tộc","cn":"","loai":"bi-thuat","loaiLabel":"Bí pháp","phamCap":"","hePhai":"Vũ tộc","soHuu":["Vũ tộc"],"blurb":"Bí pháp gọi mưa xối xả và sấm chớp, đồng thời biến những hạt mưa thành lưỡi dao công kích.","detail":"Các cường giả Vũ tộc thi triển bí pháp để tạo mưa sấm trên chiến trường, khiến một số hạt mưa trong suốt trở nên sắc bén như phi đao và lao về phía quân sĩ. Đòn công kích sau đó bị một Vương hầu phất tay áo hóa giải.","nguon":["@c0466"]},{"id":"truyen-tong-tran-te-dan-hoang-do","name":"Truyền tống trận tế đàn Hoàng đô","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Thạch Quốc"],"blurb":"Trận pháp tại tế đàn Hoàng đô, được mở bằng nghi thức hiến tế để truyền pháp chỉ tới các địa phương của Thạch Quốc.","detail":"Tế đàn trong Hoàng đô được kích hoạt, sau đó thông qua hiến tế mở Truyền tống trận để chuyển pháp chỉ kế vị của tân Nhân Hoàng tới nhiều nơi trong lãnh thổ Thạch Quốc.","nguon":["@c0467"]},{"id":"long-khi-hoang-dao-ngung-tu-cu-thu","name":"Long khí hoàng đạo ngưng tụ cự thủ","cn":"","loai":"than-thong","loaiLabel":"Thần thông hoàng đạo","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Thần thông ngưng tụ long khí hoàng đạo thành một bàn tay khổng lồ để trấn áp mục tiêu.","detail":"Thạch Hạo vận dụng long khí hoàng đạo từ trong Hoàng cung, ngưng kết thành cự thủ vươn ra ngoài nhằm trấn áp Trượng Lục.","nguon":["@c0468"]},{"id":"tran-phap-hoang-do","name":"Trận pháp Hoàng đô","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch quốc","soHuu":[],"blurb":"Trận pháp phòng hộ của Hoàng đô Thạch quốc, được mở toàn bộ khi Thạch Hạo giao chiến với sứ giả Bổ Thiên giáo.","detail":"Trận pháp phối hợp với long khí Hoàng đạo để khống chế bốn phương, ngăn dư chấn từ cuộc đối đầu giữa Thạch Hạo và Tôn giả phá hoại Hoàng thành.","nguon":["@c0469"]},{"id":"tran-phap-giam-sat-qua-to-te-dan","name":"Trận pháp giám sát qua tổ tế đàn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Trận pháp giúp quan sát và điều khiển từ xa thông qua tổ tế đàn.","detail":"Thạch Hạo kích hoạt trận pháp tại tổ tế đàn để hiện ra cảnh vật ở kiếp thổ, nhờ đó Chiến vương và Bằng Cửu có thể theo dõi đạo cô Bổ Thiên giáo cùng diễn biến của sát cục.","nguon":["@c0470"]},{"id":"sat-tran-tai-kiep-tho","name":"Sát trận tại kiếp thổ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Có thể giết Tôn giả","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Sát cục được Thạch Hạo bố trí tại nơi Nguyệt Thiền mất tích, có khả năng bao vây và luyện hóa Tôn giả.","detail":"Khi phát động, trận pháp tạo ra thần quang, lưới ánh sáng và vô số ký hiệu để phong tỏa mục tiêu. Trận xóa sổ các đệ tử Bổ Thiên giáo, sau đó luyện tan thân thể và tiêu diệt nguyên thần của đạo cô trung niên.","nguon":["@c0470"]},{"id":"tran-phap-tai-to-te-dan","name":"Trận pháp tại tổ tế đàn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chuyên đối phó Tôn giả","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Cạm bẫy tại tổ tế đàn được cải tạo để chuyên đối phó với mục tiêu cấp Tôn giả.","detail":"Thạch Hạo xóa các dấu vết còn sót lại rồi hoàn thiện trận pháp. Cạm bẫy được tính toán để phản ứng với Tôn giả, trong khi người bình thường tiến vào không bị ảnh hưởng.","nguon":["@c0470"]},{"id":"dai-tran-hoang-cung","name":"Đại trận hoàng cung","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Đại trận bảo vệ hoàng cung đã được tu bổ và thay đổi để chờ các Tôn giả xâm nhập.","detail":"Sau khi nhận tin nhiều khí tức Tôn giả của ba giáo xuất hiện ngoài Thạch đô, Thạch Hạo cho biết đại trận hoàng cung đã sẵn sàng trở thành cạm bẫy đối phó những cường giả tiến vào.","nguon":["@c0470"]},{"id":"tran-phap-than-linh-hoang-cung","name":"Trận pháp thần linh hoàng cung","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần linh","hePhai":"Thạch Quốc","soHuu":["Thạch Hạo"],"blurb":"Hệ thống phòng ngự và giám sát của hoàng cung Thạch Quốc, gồm hàng chục trận pháp liên kết chặt chẽ.","detail":"Trận pháp có thể giám sát người tiến cung và hỗ trợ điều động thế cục trong hoàng cung. Sau đại kiếp nạn, nhiều phù văn bị phá hủy vẫn chưa được sửa chữa hoàn toàn.","nguon":["@c0471"]},{"id":"dai-tran-than-linh-hoang-thanh-thach-quoc","name":"Đại trận thần linh Hoàng thành Thạch Quốc","cn":"","loai":"khac","loaiLabel":"Trận pháp phòng ngự","phamCap":"Cấp thần linh, không hoàn thiện","hePhai":"Thạch Quốc","soHuu":["Hoàng tộc Thạch Quốc"],"blurb":"Trận pháp bảo vệ Hoàng thành Thạch Quốc, đã được sửa chữa một phần và có thể tái hiện khí tức thần linh khi được tế bằng bảo liệu.","detail":"Quân thủ thành kích hoạt đại trận và thiêu đốt bảo liệu để tăng cường phòng tuyến. Trận pháp tạm thời ngăn bước đoàn Tôn giả, nhưng sau đó bị chén đen cấp thần linh áp chế, khiến phù văn trên tường thành tắt hẳn.","nguon":["@c0472"]},{"id":"su-tu-vang-tu-thu-an","name":"Sư tử vàng từ thủ ấn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Tây Phương giáo","soHuu":["Tôn giả Tây Phương giáo cầm đầu"],"blurb":"Thần thông kết ấn tạo thành sư tử vàng, chuyên dùng để công phá cửa thành.","detail":"Tôn giả Tây Phương giáo kết thủ ấn, khiến một con sư tử màu vàng xuất hiện nơi đầu ngón tay rồi lao thẳng vào cửa Hoàng thành. Cú va chạm làm phù văn lóe sáng trước khi hai cánh cửa khổng lồ nổ tung.","nguon":["@c0472"]},{"id":"bo-bo-sinh-lien","name":"Bộ bộ sinh liên","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa xác định","hePhai":"Chưa xác định","soHuu":["Thạch Hạo"],"blurb":"Mỗi bước chân của Thạch Hạo làm một đóa sen vàng xuất hiện, tỏa ra pháp quang thanh thánh và khí thế thần võ.","detail":"Dị tượng sen vàng liên tiếp sinh ra dưới chân Thạch Hạo khi nó tiến bước. Hoa sen mang ý nghĩa trọng đại đối với Tây Phương giáo, khiến Tôn giả của giáo này đặc biệt chăm chú quan sát.","nguon":["@c0473"]},{"id":"ky-lan-do-cua-bo-thien-giao","name":"Kỳ lân đỏ của Bổ Thiên giáo","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa xác định","hePhai":"Bổ Thiên giáo","soHuu":["Ông lão Bổ Thiên giáo"],"blurb":"Thần thông kết ấn hóa thành kỳ lân đỏ, được dùng để nghênh kích kiếm quang mang long khí của Thạch Hạo.","detail":"Kỳ lân đỏ lao lên đối đầu vầng kiếm quang màu vàng, tạo ra biển thần lực và mưa ánh sáng khi va chạm. Tôn giả Bổ Thiên giáo còn triển khai hình thái kỳ lân phủ đầy phù văn làm đòn sát phạt mạnh nhất.","nguon":["@c0473"]},{"id":"trang-vuc-doi-dau","name":"Tràng vực đối đầu","cn":"","loai":"khac","loaiLabel":"Tràng vực","phamCap":"Chưa xác định","hePhai":"Chưa xác định","soHuu":["Thạch Hạo","Ông lão Bổ Thiên giáo","Tôn giả Tây Phương giáo","Hai Tôn giả Bất Lão sơn","Tôn giả thứ năm của ba giáo"],"blurb":"Tràng vực tự nhiên hình thành khi khí thế của Thạch Hạo và năm Tôn giả đối đầu trực diện.","detail":"Sức mạnh và khí thế của hai phía va chạm, tạo thành một phạm vi riêng quanh chiến trường trước khi cuộc giao phong chính thức bùng nổ.","nguon":["@c0473"]},{"id":"phap-than-kim-cang","name":"Pháp thân Kim cang","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Tôn giả Tây Phương giáo cầm bình bát đen"],"blurb":"Pháp thân chiến đấu màu vàng khổng lồ, trong tay diễn hóa Hàng Ma xử.","detail":"Tôn giả Tây Phương giáo triển khai pháp thân Kim cang để giao chiến với Thạch Hạo. Pháp thân cùng Hàng Ma xử bị Côn Bằng quyền đánh rạn nứt rồi phá hủy.","nguon":["@c0474"]},{"id":"con-bang-quyen","name":"Côn Bằng quyền","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Quyền pháp do Thạch Hạo tự diễn biến, mang uy thế của Côn Bằng.","detail":"Thạch Hạo triển khai Côn Bằng quyền để đối cứng Hàng Ma xử, đánh vỡ bảo xử và phá tan pháp thân Kim cang của Tôn giả Tây Phương giáo.","nguon":["@c0474"]},{"id":"tran-phap-hoang-cung","name":"Trận pháp hoàng cung","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Thạch Quốc","soHuu":["Bằng Cửu"],"blurb":"Trận pháp trong hoàng cung Thạch Quốc, có khả năng phong tỏa và sát thương những mục tiêu đào thoát trên không.","detail":"Bằng Cửu mở trận pháp khi một nhóm môn đồ ba giáo điều khiển bảo cụ bỏ trốn. Phù văn bay lên trời, quét trúng và thiêu chết họ giữa hư không, buộc những người còn lại phải đầu hàng.","nguon":["@c0475"]},{"id":"dai-tran-cua-da-than-thach","name":"Đại trận của Đả Thần Thạch","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Đại trận do Đả Thần Thạch bố trí bằng những vật liệu thuộc tính Thổ lấy từ bảo khố hoàng cung.","detail":"Đả Thần Thạch nhận và hấp thu vật liệu thuộc tính Thổ để chuẩn bị trận pháp, đồng thời bảo đảm phù văn sẽ không xảy ra vấn đề. Theo đánh giá của Thạch Hạo, khi được bố trí hoàn chỉnh, đại trận có thể quét ngang số đông địch nhân.","nguon":["@c0475"]},{"id":"phap-mon-toan-nghe","name":"Pháp môn Toan Nghê","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật hung thú Thái cổ","phamCap":"Đại thần thông trấn quốc","hePhai":"Thạch tộc","soHuu":["Thạch Hạo"],"blurb":"Đại thần thông trấn quốc của Thạch tộc, bắt nguồn từ hung thú Thái cổ cấp Thiên và vận dụng sức mạnh lôi điện.","detail":"Thạch Hạo dành vài ngày tĩnh tâm nghiên cứu pháp môn này. Bảo thuật lấy lôi điện làm sức mạnh công kích và được ca ngợi có lực công kích vô địch.","nguon":["@c0475"]},{"id":"phong-an-tu-vi-cua-nguyet-thien","name":"Phong ấn tu vi của Nguyệt Thiền","cn":"","loai":"bi-thuat","loaiLabel":"Phong ấn","phamCap":"","hePhai":"","soHuu":[],"blurb":"Phong ấn khóa tu vi của Nguyệt Thiền, khiến nàng không thể phát huy tốc độ vốn có.","detail":"Do tu vi bị phong ấn, Nguyệt Thiền không thể dùng tốc độ để né tránh Ma nữ và buộc phải rơi vào thế bị động.","nguon":["@c0476"]},{"id":"bi-phap-thanh-khiet-cua-nguyet-thien","name":"Bí pháp thánh khiết chưa rõ tên của Nguyệt Thiền","cn":"","loai":"bi-thuat","loaiLabel":"Bí pháp","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Bí pháp tạo nên khí thế thánh khiết, hoàn mỹ, khiến người khác kính trọng và không muốn mạo phạm Nguyệt Thiền.","detail":"Khí thế do bí pháp tạo thành vẫn tồn tại khi tu vi của Nguyệt Thiền bị phong bế, nhưng không đủ ảnh hưởng đến Thạch Hạo.","nguon":["@c0477"]},{"id":"sat-tran-thu-ba","name":"Sát trận thứ ba","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Một trong ba đại sát trận của Thượng giới","hePhai":"Tiên thiên","soHuu":[],"blurb":"Một trong ba đại sát trận vô cùng mạnh mẽ của Thượng giới, có khả năng sát thương cả tồn tại cấm kỵ.","detail":"Sát trận do thiên nhiên hình thành khi khai thiên tích địa, với phù văn tự nhiên, kiếm khí và khí hỗn độn tràn ngập. Khi trận phát uy tại phế tích hoàng đô Hỏa quốc, máu của một tồn tại cấm kỵ đã đổ xuống.","nguon":["@c0478"]},{"id":"than-dan","name":"Thần Dẫn","cn":"","loai":"cong-phap","loaiLabel":"Chân giải","phamCap":"Bản thượng của Nguyên Thủy Chân Giải","hePhai":"Nguyên Thủy Chân Giải","soHuu":["Thạch Hạo"],"blurb":"Bản thượng của Nguyên Thủy Chân Giải, do Liễu Thần mang tới Thạch thôn và được Thạch Hạo lĩnh ngộ.","detail":"Phần Thạch Hạo từng có cơ hội tìm hiểu chỉ là một góc của Thần Dẫn. Liễu Thần xác nhận sự lĩnh ngộ bản thượng của hắn không có vấn đề và cho biết khi cơ duyên tới, hắn sẽ nhận được thành quả tương ứng.","nguon":["@c0478"]},{"id":"sieu-thoat","name":"Siêu Thoát","cn":"","loai":"cong-phap","loaiLabel":"Chân giải","phamCap":"Bản trung của Nguyên Thủy Chân Giải","hePhai":"Nguyên Thủy Chân Giải","soHuu":[],"blurb":"Bản trung của Nguyên Thủy Chân Giải, được cho là cất giữ trong cung điện Chí Tôn.","detail":"Siêu Thoát là mục tiêu mà các cường giả đều khao khát đạt được nhưng trước đó chưa ai thành công. Sự hiện diện của phần chân giải này trong cung điện Chí Tôn là nguyên nhân quan trọng dẫn tới cuộc tranh đoạt tại phế tích Hỏa quốc.","nguon":["@c0478"]},{"id":"sat-tran-thu-nam","name":"Sát trận thứ năm","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":[],"blurb":"Sát trận giam giữ các bá chủ và tồn tại cấm kỵ tại khu vực linh căn đệ nhất của Thượng giới.","detail":"Trận pháp có thể giết tồn tại cấm kỵ, đồng thời dẫn ánh sáng, máu, tinh khí và thần lực của kẻ chết vào trung tâm linh căn để khôi phục thần tính. Một kẻ bị giết đã tự bạo làm tổn hại một phần trận pháp; về sau sát trận bị hai bá chủ phá trong cuộc tranh đoạt linh căn.","nguon":["@c0479"]},{"id":"chu-van-vuot-gioi","name":"Chú văn vượt giới","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Những người truy kích nữ Trùng Đồng"],"blurb":"Chú văn được dùng để khai thông đường vượt giới nhằm truy bắt nữ Trùng Đồng giả.","detail":"Một số người truy kích tụng kinh, vận dụng sức mạnh chú văn để vượt giới và xuất hiện bên cạnh nữ Trùng Đồng giả sau khi nàng đoạt đóa hoa. Thủ đoạn này bị thuyền giấy nhỏ màu đen đánh tan.","nguon":["@c0479"]},{"id":"tran-phap-ho-son-bat-lao-son","name":"Trận pháp hộ sơn Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Có thể tiêu diệt Tôn giả, thậm chí thần linh","hePhai":"Bất Lão sơn","soHuu":["Bất Lão sơn"],"blurb":"Trận pháp bảo vệ Bất Lão sơn, bùng phát dày đặc ký hiệu với sức mạnh đủ tiêu diệt Tôn giả và thần linh.","detail":"Khi bà lão mang sọt thuốc xâm nhập Bất Lão sơn, trận pháp hộ sơn lập tức bùng phát sức mạnh rung trời nhưng vẫn không thể ngăn cản bà ta tiến vào trọng địa.","nguon":["@c0480"]},{"id":"dai-tran-tay-phuong-giao","name":"Đại trận Tây Phương giáo","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Nhiều tầng trận pháp thần linh","hePhai":"Tây Phương giáo","soHuu":["Tây Phương giáo"],"blurb":"Hệ thống đại trận gồm nhiều tầng trận pháp thần linh bảo vệ tịnh thổ Tây Phương giáo.","detail":"Toàn bộ đại trận được mở ra khi đạo nhân sáu tay tập kích Tây Phương giáo. Dù vậy, bàn tay của đạo nhân vẫn xuyên qua nhiều tầng phòng vệ và tiến thẳng vào cung điện chính.","nguon":["@c0480"]},{"id":"phap-than-bat-hu","name":"Pháp thân bất hủ","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Bất hủ","hePhai":"Tây Phương giáo","soHuu":["Trượng Lục"],"blurb":"Pháp thân được hiển hóa từ tượng thần phát sáng trong Tây Phương giáo, đưa Trượng Lục Kim Thân hiện thân nghênh chiến.","detail":"Khi đạo nhân sáu tay xâm nhập tịnh thổ, tượng thần phát sáng và hiển hóa pháp thân bất hủ. Trượng Lục Kim Thân từ đó bước ra đối đầu với đạo nhân rồi chuyển chiến trường tới vực ngoại.","nguon":["@c0480"]},{"id":"phap-luc-ap-che-du-ba-dai-chien","name":"Pháp lực áp chế dư ba đại chiến","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":[],"blurb":"Pháp lực bảo vệ mặt đất và sinh linh trước khí thế từ cuộc huyết chiến của các giáo chủ.","detail":"Trong đại chiến ngoài vực ngoại, có người dùng pháp lực áp chế dư ba, ngăn mặt đất và sinh linh phía dưới hóa thành tro tàn.","nguon":["@c0481"]},{"id":"tran-phap-vuot-vuc-cua-bat-lao-son","name":"Trận pháp vượt vực của Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Siêu cấp","hePhai":"Bất Lão sơn","soHuu":["Bất Lão sơn"],"blurb":"Trận pháp nối với vực bích, có thể mở thông đạo để di chuyển giữa Hoang vực và Huyền vực.","detail":"Được đặt tại một tòa thành lớn thuộc Hỏa quốc do Bất Lão sơn quản lý. Khi vận hành, trận pháp kết nối với vực bích và mở ra thông đạo màu bạc xuyên thủng hư không, đưa người sử dụng từ Hoang vực tới biên giới Huyền vực.","nguon":["@c0482"]},{"id":"tran-phap-tu-linh-trong-khoang-khach-quy","name":"Trận pháp tụ linh trong khoang khách quý","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Trận pháp được bố trí trong khoang khách quý để tập trung nguyên khí, hỗ trợ người ở bên trong tu hành.","detail":"Trận pháp tụ linh trong phòng có hiệu quả rất mạnh, khiến nguyên khí hội tụ dày đặc đến mức gần như hóa thành chất lỏng.","nguon":["@c0483"]},{"id":"phap-nhan-thong-linh","name":"Pháp nhãn thông linh","cn":"","loai":"khac","loaiLabel":"Trận pháp quan sát","phamCap":"","hePhai":"","soHuu":[],"blurb":"Pháp nhãn được khắc trên cửa sổ thủy tinh của khoang khách quý, cho phép quan sát cảnh vật ở khoảng cách xa.","detail":"Người đứng trước cửa sổ có thể nhờ Pháp nhãn thông linh nhìn rõ cảnh vật bên ngoài và quan sát vẻ tráng lệ của Huyền vực từ pháp thuyền.","nguon":["@c0483"]},{"id":"chu-tuoc","name":"Chu Tước","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Hỏa","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật được Thạch Hạo thi triển để hóa ra Chu Tước đỏ rực, đối kháng phượng hoàng lửa của Hồng Hoàng.","detail":"Thạch Hạo kết ấn gọi Chu Tước bay lên giữa ánh đỏ rực rỡ. Hình thái này hòa đấu với phượng hoàng lửa đang lao xuống trong cuộc thăm dò thực lực của Hồng Hoàng.","nguon":["@c0484"]},{"id":"phuong-hoang-lua-cua-hong-hoang","name":"Phượng hoàng lửa của Hồng Hoàng","cn":"","loai":"than-thong","loaiLabel":"Thần thông hệ Hỏa","phamCap":"","hePhai":"Hỏa","soHuu":["Hồng Hoàng"],"blurb":"Thần thông do Hồng Hoàng diễn hóa từ trăm ngàn cánh tay, hợp thành một con phượng hoàng lửa để thăm dò Thạch Hạo.","detail":"Trăm ngàn cánh tay hợp thành phượng hoàng lửa có nhiệt lực và uy thế lớn. Nó giương cánh bay lượn rồi lao thẳng xuống Thạch Hạo, đối đầu với Chu Tước do đối phương thi triển.","nguon":["@c0484"]},{"id":"dao-thai-hoan-my","name":"Đạo thai hoàn mỹ","cn":"","loai":"khac","loaiLabel":"Thể chất tu hành","phamCap":"","hePhai":"","soHuu":["Nguyệt Thiền"],"blurb":"Thể chất bẩm sinh của Nguyệt Thiền, có thể thu được vô số lợi ích khi tôi luyện trong hoàn cảnh thiên địa và pháp tắc khiếm khuyết của hạ giới.","detail":"Nguyệt Thiền sinh ra ở thượng giới với đạo thai hoàn mỹ. Nàng được đưa xuống hạ giới để rèn luyện, tận dụng môi trường có thiên địa và pháp tắc không đầy đủ nhằm thu được nhiều lợi ích trên con đường tu hành.","nguon":["@c0485"]},{"id":"sat-tran-tai-than-vuong-dien","name":"Sát trận tại Thần Vương điện","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Tần tộc"],"blurb":"Sát trận được bố trí tại Thần Vương điện để đối phó những kẻ gây xung đột.","detail":"Nhóm Tần Lập dự định chờ Thạch Hạo ra tay rồi lập tức mở sát trận, sau đó mời Tôn giả trong tộc tới trấn áp và bẻ gãy khí thế của nó.","nguon":["@c0486"]},{"id":"tran-phap-than-linh-tai-khe-nui-ngu-hanh","name":"Trận pháp thần linh tại khe núi Ngũ Hành","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần linh","hePhai":"Bất Lão sơn","soHuu":[],"blurb":"Đại trận bảo vệ khe núi Ngũ Hành, đồng thời phong tỏa tinh hoa trời đất bên trong.","detail":"Theo lời Tần Pháp, khi được mở ra, trận pháp có uy lực đủ để giết cả thần ma.","nguon":["@c0487"]},{"id":"song-giao-tien","name":"Song Giao Tiễn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Bất Lão sơn","soHuu":["Tần Pháp"],"blurb":"Thần thông hóa hai tay thành đôi giao long giao nhau, dùng để khóa chặt và kẹp nát đòn đánh hoặc binh khí của đối thủ.","detail":"Tần Pháp thi triển Song Giao Tiễn khi đối đầu trực diện với Thạch Hạo, khiến hai tay hóa thành hai con giao long lớn rồi giao nhau như ngân tiễn để kẹp lấy nắm đấm. Thần thông bị quyền lực màu vàng của Thạch Hạo đánh tan.","nguon":["@c0488"]},{"id":"kiem-tran-365-anh-kiem","name":"Kiếm trận 365 ánh kiếm","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Bất Lão sơn","soHuu":["Tần Pháp"],"blurb":"Pháp môn công kích nổi danh của Bất Lão sơn, được khắc vào máu thịt để phóng ra ba trăm sáu mươi lăm thần kiếm.","detail":"Tần Pháp tế luyện kiếm trận này trong máu thịt suốt hàng chục năm. Khi phát động, trận pháp phóng ra ba trăm sáu mươi lăm ánh kiếm, nhưng toàn bộ bị kiếm ý từ một giọt tinh huyết của Thạch Hạo phá hủy; giọt máu còn xuyên thủng cánh tay và chém nát pháp môn trong cơ thể lão.","nguon":["@c0488"]},{"id":"kiem-dao-cay-co","name":"Kiếm đạo cây cỏ","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm quyết","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Thạch Hạo"],"blurb":"Kiếm đạo dùng tinh huyết diễn hóa cây cỏ, từ đó phát ra kiếm khí vô lượng với sức sát phạt mạnh mẽ.","detail":"Thạch Hạo dùng một giọt tinh huyết mang kiếm ý diễn hóa thành cây cỏ trong hư không, phát ra kiếm mang ngập trời để phá kiếm trận của Tần Pháp. Khi đại quyết chiến bùng nổ, nó tiếp tục hiển hóa hàng chục cây cỏ chứa kiếm khí, tạo nên cảnh tượng vừa tràn đầy sinh cơ vừa ẩn chứa sát phạt, khiến Tần Pháp trúng mười ba kiếm.","nguon":["@c0488"]},{"id":"dai-tran-bat-lao-son","name":"Đại trận Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":[],"blurb":"Đại trận bao phủ khu vực tại Bất Lão sơn, có thể áp chế và dẫn động thần binh.","detail":"Khi được một ông lão Tần tộc kích hoạt, đại trận phát ra ánh sáng ngút trời, khiến thần kích trấn quốc của Thạch tộc rung chuyển dữ dội và có xu hướng bay về phía Ngũ Hành sơn.","nguon":["@c0489"]},{"id":"phap-the-bat-lao","name":"Pháp thể bất lão","cn":"","loai":"luyen-the","loaiLabel":"Luyện thể","phamCap":"Tuyệt học luyện thể","hePhai":"Bất Lão sơn","soHuu":["Tần Trạm"],"blurb":"Pháp thể tôi luyện thân thể bằng pháp lực tới mức tận cùng, giúp Tần Trạm chịu nhiều đòn đánh nghiền xương mà chưa chết.","detail":"Tần Trạm đã luyện thành pháp thể bất lão từ nhiều chục năm trước. Pháp lực gột rửa, ngưng tụ và tôi luyện thân thể khiến thể phách của lão đủ sức đối đầu Tôn giả, được so sánh với Kim cương bất hoại thân và có khả năng chịu đựng thương tổn cực nặng.","nguon":["@c0490"]},{"id":"ngu-hanh-niet-ban","name":"Ngũ hành niết bàn","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Đại pháp trấn giáo","hePhai":"Tần tộc","soHuu":["Tần Trạm","Thạch Hạo"],"blurb":"Cổ thuật niết bàn của Tần tộc có thể gột rửa người tu luyện, đồng thời ghi nhớ và sắp xếp pháp đạo từ ngoại giới.","detail":"Bí thuật ẩn trong pháp lực và huyết thanh thần thánh chảy ra từ cốt tủy Tần Trạm. Khi vận chuyển, nó hỗ trợ quá trình niết bàn, gột rửa bản thân và thu nhận pháp đạo ngoại giới; Tần Trạm định dùng khả năng này để chiếm Côn Bằng bảo thuật. Thạch Hạo thu gom các ký hiệu trong huyết thanh và đoạt được một phần truyền thừa.","nguon":["@c0490"]},{"id":"tran-phap-khac-trong-than-the-tan-tram","name":"Trận pháp khắc trong thân thể Tần Trạm","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Tần Trạm"],"blurb":"Hơn trăm trận pháp được khắc trực tiếp trong máu thịt Tần Trạm để hình thành các thông đạo tuần hoàn và phóng thích pháp lực.","detail":"Các trận pháp vận chuyển trong thân thể, dẫn thần năng từ cốt tủy tràn ra ngoài và hỗ trợ quá trình niết bàn. Khi những nguồn sức mạnh Thạch Hạo âm thầm lưu lại đồng loạt bùng nổ, hơn trăm trận pháp nhanh chóng lu mờ rồi tàn lụi, kéo theo sự sụp đổ đạo hạnh của Tần Trạm.","nguon":["@c0490"]},{"id":"phap-mon-niet-ban","name":"Pháp môn niết bàn","cn":"","loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Pháp môn truyền thừa","hePhai":"Bất Lão sơn","soHuu":["Thạch Hạo"],"blurb":"Pháp môn giúp người tu luyện gột rửa bản thân, siêu thoát khỏi ảnh hưởng của thế giới khuyết thiếu và niết bàn tái sinh mạnh hơn.","detail":"Thạch Hạo tiến vào sơn cốc, từ từ thu lấy phù văn để đạt được bản hoàn chỉnh của pháp môn. Nó nhận định truyền thừa này phù hợp với tình trạng của bản thân và có thể đem lại cơ hội siêu thoát, gột rửa rồi niết bàn tái sinh, nhưng cần lựa chọn thời cơ thích hợp mới bắt đầu tu luyện.","nguon":["@c0490"]},{"id":"tran-phap-than-linh-phong-toa-coc-than","name":"Trận pháp thần linh phong tỏa Cốc thần","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần linh","hePhai":"Bất Lão sơn","soHuu":["Lão tổ Bất Lão sơn"],"blurb":"Trận pháp thông thiên khóa chặt các khu vực trong Cốc thần, ngăn cách người bên trong với bên ngoài.","detail":"Trận pháp khiến người ở hai phía không thể nhìn hoặc nghe thấy nhau. Đả Thần Thạch nhận định việc phá giải không chỉ cần kỹ xảo mà còn đòi hỏi thực lực tương xứng.","nguon":["@c0491"]},{"id":"bao-thuat-chu-kien","name":"Bảo thuật Chư Kiền","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Ông lão Bất Lão sơn"],"blurb":"Bảo thuật diễn hóa thành Chư Kiền hung ác để công kích đối thủ.","detail":"Một ông lão Bất Lão sơn thi triển bảo thuật này khi giao chiến với Thạch Hạo. Chư Kiền do bảo thuật diễn hóa bị Chu tước bảo thuật cản lại.","nguon":["@c0491"]},{"id":"tran-phap-trong-co-the","name":"Trận pháp trong cơ thể","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Ông lão Bất Lão sơn"],"blurb":"Hệ thống hơn một trăm tòa trận pháp được một ông lão Bất Lão sơn triển khai quanh thân.","detail":"Khi được kích hoạt, hơn một trăm tòa trận pháp hiện ra xung quanh người thi triển, tạo nên cảnh tượng rộng lớn tựa một vùng sao trong lúc đối đầu Thạch Hạo.","nguon":["@c0491"]},{"id":"co-phap-niet-ban-bat-lao-son","name":"Cổ pháp niết bàn của Bất Lão sơn","cn":"","loai":"bi-thuat","loaiLabel":"Pháp quyết cấm kỵ","phamCap":"Cổ pháp hoàn thiện","hePhai":"Bất Lão sơn","soHuu":["Thạch Hạo","Tần Trạm"],"blurb":"Pháp quyết niết bàn bí truyền của nhất mạch Bất Lão sơn, chỉ một số ít người có tiềm lực lớn được tiếp nhận thiên hoàn thiện.","detail":"Thạch Hạo tinh luyện toàn bộ dấu ấn cổ pháp từ huyết thanh thần thánh của Tần Trạm và thu được thiên hoàn thiện không thiếu một chữ. Các đạo phù kết thành sách quý trong hư không, sau đó nhập vào cơ thể và khắc rõ pháp quyết trong đầu nó.","nguon":["@c0491"]},{"id":"hinh-chieu-thuong-gioi","name":"Hình chiếu thượng giới","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Bất Lão sơn","soHuu":["Tần Nhất Phàm"],"blurb":"Thần thông giúp Tần Nhất Phàm hiện hình tại Bất Lão sơn từ thượng giới.","detail":"Hình chiếu có thể điều khiển bức tranh hoàng kim và phá tan đòn đánh của Tần Vũ. Khi trận pháp tế đàn đồng ngăn cách Bất Lão sơn với thượng giới, hình chiếu nhanh chóng lu mờ và suy yếu.","nguon":["@c0492"]},{"id":"tran-phap-te-dan-dong","name":"Trận pháp tế đàn đồng","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Bất Lão sơn","soHuu":["Tần Vũ"],"blurb":"Trận pháp vận hành qua tế đàn đồng, có khả năng ngăn cách Bất Lão sơn với thượng giới.","detail":"Tần Vũ đóng trận pháp để cắt đường liên hệ giữa hai giới, khiến hình chiếu của Tần Nhất Phàm cùng bức tranh hoàng kim nhanh chóng suy yếu.","nguon":["@c0492"]},{"id":"chien-truong-anh-linh","name":"Chiến trường anh linh","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Tần Vũ"],"blurb":"Một vùng không gian đặc dị được Tần Vũ dịch chuyển tới và bố trí thành chiến trường đầy anh linh.","detail":"Chiến trường tập hợp hàng vạn anh linh cùng các linh thể màu bạc, có khả năng hình thành linh vực để dẫn dắt thần hồn của người bị nhốt rời khỏi thể xác.","nguon":["@c0493"]},{"id":"linh-vuc-mau-bac","name":"Linh vực màu bạc","cn":"","loai":"than-thong","loaiLabel":"Lĩnh vực linh hồn","phamCap":"","hePhai":"","soHuu":[],"blurb":"Không gian đặc thù hình thành từ năng lượng linh hồn của hàng vạn anh linh.","detail":"Linh vực có sức dẫn dắt thần hồn Thạch Hạo rời khỏi thể xác, nhưng cuối cùng bị thần hồn của hắn chống lại và bị pháp kiếm màu vàng xé rách.","nguon":["@c0493"]},{"id":"hoa-ma-tran","name":"Hóa ma trận","cn":"","loai":"khac","loaiLabel":"Cổ trận","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Tần Vũ"],"blurb":"Cổ trận được Tần Vũ mở ra để lôi kéo chiến ý và pháp lực của Thạch Hạo.","detail":"Trận pháp chuyển chiến ý cùng pháp lực của Thạch Hạo sang một không gian khác, hình thành một bản thể của hắn để giao chiến với Tần Hạo.","nguon":["@c0493"]},{"id":"bao-thuat-toan-nghe","name":"Bảo thuật Toan nghê","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Thạch quốc","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật điều khiển lôi điện, được Thạch Hạo phối hợp với pháp kiếm bằng bảo cốt Toan nghê để hóa giải lôi pháp của Tần Vũ.","detail":"Khi thi triển cùng pháp kiếm bảo cốt Toan nghê, bảo thuật hóa thành Toan nghê vàng hợp nhất với thần kiếm, hấp thu luồng sấm sét màu bạc rồi phát động lôi đình phản kích.","nguon":["@c0494"]},{"id":"tran-phap-khong-gian-bat-lao-son","name":"Trận pháp không gian Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Trận pháp thần linh","hePhai":"Bất Lão sơn","soHuu":["Bất Lão sơn"],"blurb":"Hệ thống trận pháp không gian dùng để giam giữ Thạch Hạo và cha mẹ cậu tại Bất Lão sơn.","detail":"Trận pháp có khả năng trói buộc và khép lại những khe nứt hư không. Vợ chồng Thạch Tử Lăng dùng dao găm tế luyện từ bảo cốt Hư không thú nhiều lần cắt mở không gian nhưng vẫn chưa thể thoát khỏi nơi giam giữ.","nguon":["@c0494"]},{"id":"nguyen-rua-than-hon-cua-tan-vu","name":"Nguyền rủa thần hồn của Tần Vũ","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thần thuật","hePhai":"Bất Lão sơn","soHuu":["Tần Vũ"],"blurb":"Thần thuật tạo ra gợn sóng bạc mang sức nguyền rủa, có thể bám lên mục tiêu và khiến thần hồn tan biến khi phát tác.","detail":"Tần Vũ thi triển thuật này nhằm vào Thạch Hạo. Gợn sóng nguyền rủa có đặc tính bám trên thân thể và không phai nhạt, nhưng chưa kịp chạm tới mục tiêu đã bị một tia khí tức của Tiểu Tháp sấy khô.","nguon":["@c0495"]},{"id":"than-thuat-nguyen-to-ngu-hanh-cua-tan-vu","name":"Thần thuật nguyên tố ngũ hành của Tần Vũ","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thần thuật","hePhai":"Bất Lão sơn","soHuu":["Tần Vũ"],"blurb":"Thần thuật hiến tế thân thể để dẫn động sức mạnh ngũ hành và nguyền rủa công kích đối phương.","detail":"Sau khi bị chặt tay, Tần Vũ cho cánh tay đứt nổ tung làm vật hiến tế rồi thi triển thần thuật nhằm phế bỏ Thạch Hạo. Tinh hoa bản nguyên sinh ra từ cánh tay lại bị Chí tôn cốt hấp thu và luyện hóa thành sức mạnh thần tính.","nguon":["@c0495"]},{"id":"tran-phap-thong-gioi-bat-lao-son","name":"Trận pháp thông giới của Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Bất Lão sơn"],"blurb":"Trận pháp kết nối hạ giới với thượng giới của Bất Lão sơn.","detail":"Đại Ma Thần và A Man đã bước vào trận pháp này để rời hạ giới, tiến lên thượng giới.","nguon":["@c0496"]},{"id":"phap-kiem-hoa-toan-nghe","name":"Pháp kiếm hóa Toan Nghê","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thần thông biến pháp kiếm thành Toan Nghê màu vàng mang theo sức mạnh sấm sét.","detail":"Thạch Hạo thi triển phép biến hóa trên pháp kiếm, tạo thành Toan Nghê màu vàng giữa sấm chớp và dùng nó đánh Tần Pháp thành tro.","nguon":["@c0496"]},{"id":"hien-te-thuc-tinh-bat-lao-son","name":"Hiến tế thức tỉnh Bất Lão sơn","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật hiến tế","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Tần Vũ"],"blurb":"Bí thuật hiến tế dùng việc thiêu đốt bản thân để cầu gọi lực lượng trấn thủ của Bất Lão sơn.","detail":"Khi không thể thoát thân, Tần Vũ ngâm thần chú và thiêu đốt chính mình, khiến Ngũ hành sơn phát uy và đánh thức lực lượng đang trấn thủ Bất Lão sơn.","nguon":["@c0496"]},{"id":"bi-phap-khoa-chat-tinh-khi","name":"Bí pháp khóa chặt tinh khí","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Sinh linh bất diệt"],"blurb":"Bí pháp khóa kín tinh khí toàn thân, giảm tiêu hao xuống mức thấp nhất để duy trì sinh mệnh qua năm tháng dài lâu.","detail":"Sinh linh bị trấn áp dưới Ngũ Hành sơn vận dụng bí pháp này để chống lại sự bào mòn của thời gian, sống sót qua vô tận năm tháng dù đạo cốt bị giày vò và chân hồn bị luyện hóa.","nguon":["@c0497"]},{"id":"kiem-mang-hon-don-cua-tieu-thap","name":"Kiếm mang hỗn độn của Tiểu Tháp","cn":"","loai":"than-thong","loaiLabel":"Thần thông công kích","phamCap":"Chưa rõ","hePhai":"Hỗn độn","soHuu":["Tiểu Tháp"],"blurb":"Kiếm mang hỗn độn có sức chém phá mạnh mẽ, được Tiểu Tháp dùng để đối kháng pháp tắc và công kích từ khoảng cách rất xa.","detail":"Khi Tiểu Tháp toàn lực thi triển, từng luồng kiếm khí hỗn độn giáng xuống, giao chiến với Ngũ Hành sơn và hai lần chém vào sinh linh bị trấn áp. Đòn đánh có thể uy hiếp pháp khí sinh trong hỗn độn, nhưng lần công kích đầu tiên chỉ chém đứt một sợi tóc của sinh linh ấy.","nguon":["@c0497"]},{"id":"dau-an-van-vat-chan-linh","name":"Dấu ấn vạn vật chân linh","cn":"","loai":"than-thong","loaiLabel":"Thần thông pháp tắc","phamCap":"Chưa rõ","hePhai":"Chân linh","soHuu":["Tiểu Tháp"],"blurb":"Thần thông hiện hóa dấu ấn của nhiều loài chân linh thành chim thần và mãnh thú, mang pháp lực mạnh mẽ để phá sức giam cầm.","detail":"Trên thân Tiểu Tháp hiện ra dấu ấn Toan nghê, Đại bàng, Thao thiết cùng nhiều chân linh khác. Các dấu ấn hóa thành chim thần và mãnh thú, cắt đứt thiên địa và phá tan lực giam cầm Ngũ hành trong cuộc đối kháng với Ngũ Hành sơn.","nguon":["@c0497"]},{"id":"quyen-an-khong-ten-cua-sinh-linh-bat-diet","name":"Quyền ấn không tên của sinh linh bất diệt","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Sinh linh bất diệt bị xích thần Ngũ hành trói buộc"],"blurb":"Quyền ấn được sinh linh bất diệt thi triển để chống lại sức trấn áp từ Ngũ hành sơn và điều động sức mạnh ngoại giới.","detail":"Sinh linh bất diệt kết thành quyền ấn hướng lên hư không để phòng ngự. Khi quyền ấn xuất hiện, sức mạnh của một giới dường như bị rút lấy nhằm đối kháng sự trấn áp của Ngũ hành sơn.","nguon":["@c0498"]},{"id":"than-thong-doi-canh-chim-mau-vang-chua-ro-ten","name":"Thần thông đôi cánh chim màu vàng chưa rõ tên","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Sinh linh bất diệt bị xích thần Ngũ hành trói buộc"],"blurb":"Thần thông hiển hóa đôi cánh chim màu vàng khổng lồ, dùng thần mang và gợn sóng mạnh mẽ để chống sức trấn áp của Ngũ hành sơn.","detail":"Sinh linh bất diệt hiển hóa sau lưng một đôi cánh chim màu vàng rộng lớn hơn núi cao. Đôi cánh phát ra thần mang vô lượng cùng gợn sóng chí cường, nâng đỡ trời xanh và trực tiếp đối kháng Ngũ hành sơn.","nguon":["@c0498"]},{"id":"ke-hoach-chi-ton-niet-ban","name":"Kế hoạch Chí tôn niết bàn","cn":"","loai":"bi-thuat","loaiLabel":"Phương pháp huyết mạch","phamCap":"Chưa rõ","hePhai":"Tần tộc thượng giới","soHuu":[],"blurb":"Phương pháp do Tần tộc thượng giới nghiên cứu nhằm tạo ra hậu duệ có huyết mạch mạnh, lấy tinh huyết của người em để cứu người anh.","detail":"Tần tộc thượng giới bí mật đưa một khối Thiên cốt thần bí, bảo dược và những phương pháp đặc biệt xuống hạ giới, yêu cầu vợ chồng Thạch Tử Lăng sinh thêm một người con. Theo kế hoạch, tinh huyết của người em sẽ được dùng để tẩm bổ và cứu Thạch Hạo, người đã mất Chí Tôn cốt.","nguon":["@c0499"]},{"id":"co-truyen-tong-tran-len-thuong-gioi","name":"Cổ truyền tống trận lên thượng giới","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Cổ trận","hePhai":"","soHuu":["Tần Hạo"],"blurb":"Một trận pháp cổ xưa được Tần Hạo sử dụng để giúp Lão Thập Ngũ và A Man thoát vây.","detail":"Trong lúc vận chuyển, trận pháp xảy ra sai lệch ngoài dự liệu, đưa Lão Thập Ngũ và A Man trực tiếp tiến lên thượng giới.","nguon":["@c0500"]}]};